(299013,33224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... tarro dorado para tu cabeza es muy guay.'::text,'este'::text,'estos'::text,'esos'::text,'Sinceramente, este tarro dorado para tu cabeza es muy guay.'::text),
(299012,33224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ... pot doré pour ta tête est trop cool.'::text,'ce'::text,'ces'::text,'ces'::text,'Franchement, ce pot doré pour ta tête est trop cool.'::text),
(299015,33224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, kafan için ... altın kavanoz çok havalı.'::text,'bu'::text,'bu'::text,'şu'::text,'Açıkçası, kafan için bu altın kavanoz çok havalı.'::text),
(299016,33224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... az arany tégelyke a fejedre nagyon menő.'::text,'ez'::text,'ezek'::text,'azok'::text,'Őszintén, ez az arany tégelyke a fejedre nagyon menő.'::text),
(299019,33225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, die Creme auf ... Kopf ist ein mutiger Move.'::text,'deinem'::text,'dir'::text,'deiner'::text,'Ehrlich, die Creme auf deinem Kopf ist ein mutiger Move.'::text),
(299023,33225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, крем на ... голові — це сміливий хід.'::text,'твоїй'::text,'ти'::text,'твоїй'::text,'Чесно, крем на твоїй голові — це сміливий хід.'::text),
(299022,33225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, la crema en ... cabeza es una jugada atrevida.'::text,'tu'::text,'tú'::text,'tuya'::text,'Sinceramente, la crema en tu cabeza es una jugada atrevida.'::text),
(299021,33225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la crème sur ... tête, c''est un move audacieux.'::text,'ta'::text,'toi'::text,'la tienne'::text,'Franchement, la crème sur ta tête, c''est un move audacieux.'::text),
(299024,33225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, ... kafandaki krem cesur bir hamle.'::text,'senin'::text,'sen'::text,'seninki'::text,'Açıkçası, senin kafandaki krem cesur bir hamle.'::text),
(299025,33225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a krém a ... merész húzás.'::text,'fejeden'::text,'te'::text,'tiéd'::text,'Őszintén, a krém a fejeden merész húzás.'::text),
(299028,33226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fällt der Katze auf den Kopf? Ein goldener Tropfen.'::text,'Was'::text,'Wer'::text,'Wo'::text,'Was fällt der Katze auf den Kopf? Ein goldener Tropfen.'::text),
(299032,33226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... падає коту на голову? Золота крапля.'::text,'Що'::text,'Хто'::text,'Де'::text,'Що падає коту на голову? Золота крапля.'::text),
(299031,33226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... cae en la cabeza del gato? Una gota dorada.'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué cae en la cabeza del gato? Una gota dorada.'::text),
(299030,33226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tombe sur la tête du chat ? Une goutte dorée.'::text,'Qu''est-ce qui'::text,'Qui'::text,'Où'::text,'Qu''est-ce qui tombe sur la tête du chat ? Une goutte dorée.'::text),
(299033,33226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedinin kafasına ... düşüyor? Altın bir damla.'::text,'ne'::text,'kim'::text,'nerede'::text,'Kedinin kafasına ne düşüyor? Altın bir damla.'::text),
(299034,33226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... esik a macska fejére? Egy arany csepp.'::text,'Mi'::text,'Ki'::text,'Hol'::text,'Mi esik a macska fejére? Egy arany csepp.'::text),
(299037,33227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein goldener Tropfen landet ... seiner Glatze.'::text,'auf'::text,'in'::text,'an'::text,'Ein goldener Tropfen landet auf seiner Glatze.'::text),
(299041,33227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Золота крапля падає ... його лису голову.'::text,'на'::text,'в'::text,'біля'::text,'Золота крапля падає на його лису голову.'::text),
(299040,33227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una gota dorada cae ... su cabeza calva.'::text,'sobre'::text,'en'::text,'a'::text,'Una gota dorada cae sobre su cabeza calva.'::text),
(299039,33227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une goutte dorée atterrit ... son crâne chauve.'::text,'sur'::text,'dans'::text,'à'::text,'Une goutte dorée atterrit sur son crâne chauve.'::text),
(299042,33227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Altın bir damla onun kel kafasının ... düşüyor.'::text,'üstüne'::text,'içine'::text,NULL::text,'Altın bir damla onun kel kafasının üstüne düşüyor.'::text),
(299043,33227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy arany csepp a kopasz ... landol.'::text,'fején'::text,'fejében'::text,'fejénél'::text,'Egy arany csepp a kopasz fején landol.'::text),
(299046,33228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo Alter, ... Köpfe haben neue Haare bekommen. Da muss ein Kamm her!'::text,'Zwei'::text,'Zweite'::text,'Zweien'::text,'Yo Alter, Zwei Köpfe haben neue Haare bekommen. Da muss ein Kamm her!'::text),
(299050,33228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бро, ... голови отримали нове волосся. Знадобиться гребінець!'::text,'Дві'::text,'Друга'::text,'Двійки'::text,'Йо, бро, Дві голови отримали нове волосся. Знадобиться гребінець!'::text),
(299049,33228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, a ... cabezas les ha salido pelo nuevo. ¡Va a hacer falta un peine!'::text,'dos'::text,'segunda'::text,'dos'::text,'Tío, a dos cabezas les ha salido pelo nuevo. ¡Va a hacer falta un peine!'::text),
(299048,33228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... têtes ont de nouveaux cheveux. Faudra un peigne !'::text,'Deux'::text,'Deuxième'::text,'Deux'::text,'Frère, Deux têtes ont de nouveaux cheveux. Faudra un peigne !'::text),
(299051,33228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... kafada yeni saçlar çıktı. Tarak lazım olacak!'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Kanka, iki kafada yeni saçlar çıktı. Tarak lazım olacak!'::text),
(299052,33228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... fejen új haj nőtt. Kelleni fog egy fésű!'::text,'két'::text,'második'::text,'kettesek'::text,'Tesó, két fejen új haj nőtt. Kelleni fog egy fésű!'::text),
(328107,36457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze hat Berge von Arbeit, also ... sie heute Abend lange bleiben.'::text,'wird'::text,'wird'::text,NULL::text,'Die Katze hat Berge von Arbeit, also wird sie heute Abend lange bleiben.'::text),
(328111,36457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кота купа роботи, тож він сьогодні ввечері ... допізна.'::text,'збирається затриматися'::text,'затримається'::text,NULL::text,'У кота купа роботи, тож він сьогодні ввечері збирається затриматися допізна.'::text),
(328110,36457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato tiene montañas de trabajo, así que esta noche ... hasta tarde.'::text,'se va a quedar'::text,'se quedará'::text,NULL::text,'El gato tiene montañas de trabajo, así que esta noche se va a quedar hasta tarde.'::text),
(328109,36457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat a des piles de boulot, alors il ... tard ce soir.'::text,'va rester'::text,'restera'::text,NULL::text,'Le chat a des piles de boulot, alors il va rester tard ce soir.'::text),
(328112,36457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedinin yığınla işi var, bu yüzden bu akşam geç saate kadar ...'::text,'kalacak'::text,'kalacak'::text,NULL::text,'Kedinin yığınla işi var, bu yüzden bu akşam geç saate kadar kalacak.'::text),
(328113,36457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macskának egy csomó munkája van, ezért ma este sokáig ... bent maradni.'::text,'fog'::text,'fog'::text,NULL::text,'A macskának egy csomó munkája van, ezért ma este sokáig fog bent maradni.'::text),
(328116,36458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze im Anzug hat eine Menge ...'::text,'Arbeit'::text,'Arbeit'::text,'eine Arbeit'::text,'Die Katze im Anzug hat eine Menge Arbeit.'::text),
(328120,36458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кота в костюмі багато ...'::text,'роботи'::text,'робіт'::text,'роботи'::text,'У кота в костюмі багато роботи.'::text),
(328119,36458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato del traje tiene mucho ...'::text,'trabajo'::text,'trabajo'::text,'un trabajo'::text,'El gato del traje tiene mucho trabajo.'::text),
(328118,36458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat en costume a beaucoup de ...'::text,'travail'::text,'travail'::text,'un travail'::text,'Le chat en costume a beaucoup de travail.'::text),
(328121,36458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım elbiseli kedinin bir sürü ... var.'::text,'işi'::text,'işleri'::text,'bir işi'::text,'Takım elbiseli kedinin bir sürü işi var.'::text),
(328122,36458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az öltönyös macskának rengeteg ... van.'::text,'munkája'::text,'munkája'::text,'egy munkája'::text,'Az öltönyös macskának rengeteg munkája van.'::text),
(328125,36459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gönn ich ihm: so ... Arbeit, dass er sie mit ins Bett nimmt.'::text,'viel'::text,'viele'::text,'irgendwelche'::text,'Gönn ich ihm: so viel Arbeit, dass er sie mit ins Bett nimmt.'::text),
(328129,36459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ну клас, рада за нього: так ... роботи, що він бере її в ліжко.'::text,'багато'::text,'багато'::text,'будь-якої'::text,'Ну клас, рада за нього: так багато роботи, що він бере її в ліжко.'::text),
(328128,36459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué bien por él: ... trabajo que se lo lleva a la cama.'::text,'tanto'::text,'tantos'::text,'cualquier'::text,'Qué bien por él: tanto trabajo que se lo lleva a la cama.'::text),
(328127,36459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trop contente pour lui : ... travail qu''il l''emporte au lit.'::text,'tant de'::text,'tant de'::text,'n''importe quel'::text,'Trop contente pour lui : tant de travail qu''il l''emporte au lit.'::text),
(328130,36459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ona çok yakıştı: o kadar ... iş var ki yatağa bile götürüyor.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Ona çok yakıştı: o kadar çok iş var ki yatağa bile götürüyor.'::text),
(328131,36459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Örülök neki: olyan ... munkája van, hogy még az ágyba is viszi.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Örülök neki: olyan sok munkája van, hogy még az ágyba is viszi.'::text),
(328134,36460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So ein entspannter Job, logisch: Auf seinem Schreibtisch ... Stapel von Arbeit.'::text,'sind'::text,'ist'::text,'sein'::text,'So ein entspannter Job, logisch: Auf seinem Schreibtisch sind Stapel von Arbeit.'::text),
(328138,36460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Така розслаблена робота, звісно: на його столі ... стоси роботи.'::text,'є'::text,'є'::text,'бути'::text,'Така розслаблена робота, звісно: на його столі є стоси роботи.'::text),
(328137,36460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué trabajo tan relajado, claro: ... montones de trabajo en su escritorio.'::text,'hay'::text,'hay'::text,'hay'::text,'Qué trabajo tan relajado, claro: hay montones de trabajo en su escritorio.'::text),
(328136,36460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un job trop relaxant, évidemment : ... des piles de boulot sur son bureau.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Un job trop relaxant, évidemment : il y a des piles de boulot sur son bureau.'::text),
(328139,36460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne rahat bir iş, belli ki: masasında yığın yığın iş ...'::text,'var'::text,'var'::text,'olmak'::text,'Ne rahat bir iş, belli ki: masasında yığın yığın iş var.'::text),
(328140,36460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda pihentető meló, persze: az asztalán munkakupacok ...'::text,'vannak'::text,'van'::text,'lenni'::text,'Micsoda pihentető meló, persze: az asztalán munkakupacok vannak.'::text),
(328143,36461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, der Chef hat''s gesagt: Der Kater ... heute Abend seine Arbeit fertig machen, Alter.'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Nee, der Chef hat''s gesagt: Der Kater muss heute Abend seine Arbeit fertig machen, Alter.'::text),
(328147,36461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бос так сказав: кіт ... закінчити свою роботу сьогодні ввечері, бро.'::text,'має'::text,'мусить'::text,'не має'::text,'Не, бос так сказав: кіт має закінчити свою роботу сьогодні ввечері, бро.'::text),
(328146,36461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, lo dijo el jefe: el gato ... terminar su trabajo esta noche, tío.'::text,'tiene que'::text,'debe'::text,'no tiene que'::text,'Qué va, lo dijo el jefe: el gato tiene que terminar su trabajo esta noche, tío.'::text),
(328145,36461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, c''est le boss qui l''a dit : le chat ... finir son boulot ce soir, frère.'::text,'doit'::text,'doit'::text,'n''a pas à'::text,'Non, c''est le boss qui l''a dit : le chat doit finir son boulot ce soir, frère.'::text),
(328148,36461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, patron öyle dedi: kedi işini bu akşam ..., kanka.'::text,'bitirmek zorunda'::text,'bitirmeli'::text,'bitirmek zorunda değil'::text,'Yok, patron öyle dedi: kedi işini bu akşam bitirmek zorunda, kanka.'::text),
(328149,36461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, a főnök mondta: a macskának ma este ... befejeznie a munkáját, tesó.'::text,'kell'::text,'kell'::text,'nem kell'::text,'Nem, a főnök mondta: a macskának ma este kell befejeznie a munkáját, tesó.'::text),
(328161,36463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline um 21 Uhr, ... nimmt die Katze ihre Arbeit mit ins Bett.'::text,'also'::text,'aber'::text,'weil'::text,'Deadline um 21 Uhr, also nimmt die Katze ihre Arbeit mit ins Bett.'::text),
(328165,36463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн о 21:00, ... кіт бере свою роботу в ліжко.'::text,'тому'::text,'але'::text,'бо'::text,'Дедлайн о 21:00, тому кіт бере свою роботу в ліжко.'::text),
(328164,36463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline a las 21:00, ... el gato se lleva el trabajo a la cama.'::text,'así que'::text,'pero'::text,'porque'::text,'Deadline a las 21:00, así que el gato se lleva el trabajo a la cama.'::text),
(328163,36463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline à 21 h, ... le chat emporte son travail au lit.'::text,'donc'::text,'mais'::text,'parce que'::text,'Deadline à 21 h, donc le chat emporte son travail au lit.'::text),
(328166,36463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline 21:00, ... kedi işini yatağa götürüyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Deadline 21:00, bu yüzden kedi işini yatağa götürüyor.'::text),
(328167,36463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Határidő este 9, ... a macska ágyba viszi a munkáját.'::text,'ezért'::text,'de'::text,'mert'::text,'Határidő este 9, ezért a macska ágyba viszi a munkáját.'::text),
