(327353,36373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bord de la cascade ... très large.'::text,'est'::text,'sont'::text,'suis'::text,'Le bord de la cascade est très large.'::text),
(327356,36373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şelalenin kenarı çok geniş ...'::text,''::text,NULL::text,NULL::text,'Şelalenin kenarı çok geniş.'::text),
(327357,36373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vízesés pereme ... nagyon széles.'::text,''::text,NULL::text,'vagyok'::text,'A vízesés pereme nagyon széles.'::text),
(327369,36375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Leute ... das ferne Ufer über den breiten Fluss hinweg sehen.'::text,'können'::text,'können'::text,'sind'::text,'Die Leute können das ferne Ufer über den breiten Fluss hinweg sehen.'::text),
(327373,36375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди ... бачити далекий берег через широку річку.'::text,'можуть'::text,'можуть'::text,'є'::text,'Люди можуть бачити далекий берег через широку річку.'::text),
(327372,36375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las personas ... ver la orilla lejana al otro lado del ancho río.'::text,'pueden'::text,'pueden'::text,'están'::text,'Las personas pueden ver la orilla lejana al otro lado del ancho río.'::text),
(327371,36375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens ... voir la rive lointaine de l''autre côté du large fleuve.'::text,'peuvent'::text,'peuvent'::text,'sont'::text,'Les gens peuvent voir la rive lointaine de l''autre côté du large fleuve.'::text),
