(306045,34005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők egy monitoron ... a filmet a sivatagban.'::text,'nézik'::text,'nézi'::text,'néző'::text,'Ők egy monitoron nézik a filmet a sivatagban.'::text),
