(306052,34006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленька камера ... зняти великий фільм.'::text,'може'::text,'може'::text,'є'::text,'Маленька камера може зняти великий фільм.'::text),
(306051,34006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una cámara pequeña ... hacer una gran peli.'::text,'puede'::text,'puede'::text,'está'::text,'Una cámara pequeña puede hacer una gran peli.'::text),
(306050,34006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une petite caméra ... faire un grand film.'::text,'peut'::text,'peut'::text,'est'::text,'Une petite caméra peut faire un grand film.'::text),
(306053,34006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük bir kamera büyük bir film ...'::text,'çekebilir'::text,'çekebilir'::text,NULL::text,'Küçük bir kamera büyük bir film çekebilir.'::text),
(306054,34006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kis kamera nagy filmet ... csinálni.'::text,'tud'::text,'tud'::text,'van'::text,'Egy kis kamera nagy filmet tud csinálni.'::text),
(306075,34009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine eigene Idee, natürlich genial: Er ... den Film mit einer winzigen Kamera drehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Seine eigene Idee, natürlich genial: Er muss den Film mit einer winzigen Kamera drehen.'::text),
(306079,34009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його власна ідея, звісно, геніальна: він ... зняти фільм на крихітну камеру.'::text,'мусить'::text,'має'::text,'мав би'::text,'Його власна ідея, звісно, геніальна: він мусить зняти фільм на крихітну камеру.'::text),
(306078,34009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Idea suya, genial, claro: él ... rodar la peli con una cámara diminuta.'::text,'debe'::text,'tiene que'::text,'debería'::text,'Idea suya, genial, claro: él debe rodar la peli con una cámara diminuta.'::text),
(306077,34009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son idée à lui, évidemment géniale : il ... tourner le film avec une caméra minuscule.'::text,'doit'::text,'doit'::text,'devrait'::text,'Son idée à lui, évidemment géniale : il doit tourner le film avec une caméra minuscule.'::text),
(306080,34009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendi fikri, tabii ki dâhiyane: filmi minicik bir kamerayla ...'::text,'çekmeli'::text,'çekmek zorunda'::text,'çekmeli'::text,'Kendi fikri, tabii ki dâhiyane: filmi minicik bir kamerayla çekmeli.'::text),
(306081,34009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A saját ötlete, persze zseniális: egy apró kamerával ... leforgatnia a filmet.'::text,'kell'::text,'kell'::text,'kellene'::text,'A saját ötlete, persze zseniális: egy apró kamerával kell leforgatnia a filmet.'::text),
(306084,34010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ein Film, gedreht mit einer winzigen Kamera? Du ... ihn dir anschauen, echt.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Alter, ein Film, gedreht mit einer winzigen Kamera? Du solltest ihn dir anschauen, echt.'::text),
(306088,34010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, фільм, знятий на крихітну камеру? Ти ... його подивитися, чесно.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Бро, фільм, знятий на крихітну камеру? Ти мав би його подивитися, чесно.'::text),
(306087,34010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿una peli rodada con una cámara diminuta? ... verla, en serio.'::text,'Deberías'::text,'Deberías'::text,'Deberías'::text,'Tío, ¿una peli rodada con una cámara diminuta? Deberías verla, en serio.'::text),
(306086,34010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, un film tourné avec une caméra minuscule ? Tu ... le regarder, sérieux.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Frère, un film tourné avec une caméra minuscule ? Tu devrais le regarder, sérieux.'::text),
(306089,34010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, minicik bir kamerayla çekilmiş film mi? Onu ..., cidden.'::text,'izlemelisin'::text,'izlemelisin'::text,'izlemelisin'::text,'Kanka, minicik bir kamerayla çekilmiş film mi? Onu izlemelisin, cidden.'::text),
(306090,34010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egy apró kamerával forgatott film? Meg ... nézned, komolyan.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Tesó, egy apró kamerával forgatott film? Meg kellene nézned, komolyan.'::text),
(306093,34011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, die Kamera ist winzig, ... der Film sieht riesig aus, ohne Witz.'::text,'aber'::text,'also'::text,'weil'::text,'Nee Alter, die Kamera ist winzig, aber der Film sieht riesig aus, ohne Witz.'::text),
(306097,34011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, камера крихітна, ... фільм виглядає величезним, без брехні.'::text,'але'::text,'тому'::text,'бо'::text,'Не, бро, камера крихітна, але фільм виглядає величезним, без брехні.'::text),
(306096,34011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, la cámara es diminuta, ... la peli parece enorme, en serio.'::text,'pero'::text,'así que'::text,'porque'::text,'Qué va, tío, la cámara es diminuta, pero la peli parece enorme, en serio.'::text),
(306095,34011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, la caméra est minuscule, ... le film a l''air énorme, sans mentir.'::text,'mais'::text,'donc'::text,'parce que'::text,'Non frère, la caméra est minuscule, mais le film a l''air énorme, sans mentir.'::text),
(306098,34011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, kamera minicik ... film devasa görünüyor, yemin ederim.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Yok kanka, kamera minicik ama film devasa görünüyor, yemin ederim.'::text),
(306099,34011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, a kamera pici, ... a film óriásinak tűnik, komolyan.'::text,'de'::text,'ezért'::text,'mert'::text,'Á, tesó, a kamera pici, de a film óriásinak tűnik, komolyan.'::text),
(295356,32818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... schneidet das Netz durch? Ein Schnorchler, und die Schildkröte ist frei.'::text,'Wer'::text,'Was'::text,'Wo'::text,'Wer schneidet das Netz durch? Ein Schnorchler, und die Schildkröte ist frei.'::text),
(295360,32818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... розрізає сітку? Сноркелер, і черепаха вільна.'::text,'Хто'::text,'Що'::text,'Де'::text,'Хто розрізає сітку? Сноркелер, і черепаха вільна.'::text),
(295359,32818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... corta la red? Un buceador, y la tortuga queda libre.'::text,'Quién'::text,'Qué'::text,'Dónde'::text,'¿Quién corta la red? Un buceador, y la tortuga queda libre.'::text),
(295358,32818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... coupe le filet ? Un plongeur en apnée, et la tortue est libre.'::text,'Qui'::text,'Qu''est-ce qui'::text,'Où'::text,'Qui coupe le filet ? Un plongeur en apnée, et la tortue est libre.'::text),
(295361,32818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağı ... kesiyor? Bir şnorkelci ve kaplumbağa özgür.'::text,'kim'::text,'ne'::text,'nerede'::text,'Ağı kim kesiyor? Bir şnorkelci ve kaplumbağa özgür.'::text),
(295362,32818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... vágja el a hálót? Egy sznorkelező, és a teknős szabad.'::text,'Ki'::text,'Mi'::text,'Hol'::text,'Ki vágja el a hálót? Egy sznorkelező, és a teknős szabad.'::text),
(295365,32819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ein perfekter Schwimmausflug, logisch: Die Schildkröte ... aus einem Netz frei.'::text,'kam'::text,'kommt'::text,'kam'::text,'Gestern ein perfekter Schwimmausflug, logisch: Die Schildkröte kam aus einem Netz frei.'::text),
(295369,32819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ідеальне плавання, звісно: черепаха ... із сітки.'::text,'вибралася'::text,'вибирається'::text,'вибралася'::text,'Учора ідеальне плавання, звісно: черепаха вибралася із сітки.'::text),
(295368,32819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un baño perfecto ayer, claro: la tortuga ... de una red.'::text,'se liberó'::text,'se libera'::text,'se liberó'::text,'Un baño perfecto ayer, claro: la tortuga se liberó de una red.'::text),
(295367,32819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une baignade parfaite hier, évidemment : la tortue ... d''un filet.'::text,'s''est libérée'::text,'se libère'::text,'s''est libérée'::text,'Une baignade parfaite hier, évidemment : la tortue s''est libérée d''un filet.'::text),
(295370,32819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün mükemmel bir yüzüş, tabii ki: kaplumbağa bir ağdan ...'::text,'kurtuldu'::text,'kurtulur'::text,'kurtuldu'::text,'Dün mükemmel bir yüzüş, tabii ki: kaplumbağa bir ağdan kurtuldu.'::text),
(295371,32819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap tökéletes úszás, persze: a teknős ... egy hálóból.'::text,'kiszabadult'::text,'kiszabadul'::text,'kiszabadult'::text,'Tegnap tökéletes úszás, persze: a teknős kiszabadult egy hálóból.'::text),
(295374,32820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos: Die Schildkröte schwimmt normalerweise frei, aber gestern ... sie in einem Netz fest.'::text,'hing'::text,'hängt'::text,NULL::text,'Makellos: Die Schildkröte schwimmt normalerweise frei, aber gestern hing sie in einem Netz fest.'::text),
(295378,32820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно: черепаха зазвичай плаває вільно, а вчора ... в сітці.'::text,'застрягла'::text,'застрягає'::text,NULL::text,'Бездоганно: черепаха зазвичай плаває вільно, а вчора застрягла в сітці.'::text),
(295377,32820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable: la tortuga suele nadar libre, pero ayer ... en una red.'::text,'se quedó atrapada'::text,'se queda atrapada'::text,NULL::text,'Impecable: la tortuga suele nadar libre, pero ayer se quedó atrapada en una red.'::text),
(295376,32820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impeccable : la tortue nage libre d''habitude, mais hier elle ... dans un filet.'::text,'est restée coincée'::text,'reste coincée'::text,NULL::text,'Impeccable : la tortue nage libre d''habitude, mais hier elle est restée coincée dans un filet.'::text),
(295379,32820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz: kaplumbağa genelde özgürce yüzer ama dün bir ağa ...'::text,'takıldı'::text,'takılır'::text,NULL::text,'Kusursuz: kaplumbağa genelde özgürce yüzer ama dün bir ağa takıldı.'::text),
(295380,32820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan: a teknős általában szabadon úszik, de tegnap ... egy hálón.'::text,'fennakadt'::text,'fennakad'::text,NULL::text,'Hibátlan: a teknős általában szabadon úszik, de tegnap fennakadt egy hálón.'::text),
(295383,32821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... gerade jetzt die Schildkröte, ohne Witz.'::text,'befreien'::text,'befreien'::text,'befreit'::text,'Yo, sie befreien gerade jetzt die Schildkröte, ohne Witz.'::text),
(295387,32821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вони саме зараз ... черепаху, без брехні.'::text,'звільняють'::text,'звільняють'::text,'звільняє'::text,'Йо, вони саме зараз звільняють черепаху, без брехні.'::text),
(295386,32821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ahora mismo ... a la tortuga, en serio.'::text,'están liberando'::text,'liberan'::text,'está liberando'::text,'Tío, ahora mismo están liberando a la tortuga, en serio.'::text),
(295385,32821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ils ... la tortue en ce moment, sans mentir.'::text,'sont en train de libérer'::text,'libèrent'::text,'est en train de libérer'::text,'Yo, ils sont en train de libérer la tortue en ce moment, sans mentir.'::text),
(295388,32821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şu an kaplumbağayı ..., yemin ederim.'::text,'kurtarıyorlar'::text,'kurtarırlar'::text,'kurtarıyor'::text,'Kanka, şu an kaplumbağayı kurtarıyorlar, yemin ederim.'::text),
(295389,32821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, most épp ... a teknőst, komolyan.'::text,'kiszabadítják'::text,'kiszabadítják'::text,'kiszabadítja'::text,'Figyu, most épp kiszabadítják a teknőst, komolyan.'::text),
(295392,32822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, Schildkröten schwimmen normalerweise frei, aber diese hier ... in einem Netz, echt.'::text,'wartet'::text,'wartet'::text,NULL::text,'Alter, Schildkröten schwimmen normalerweise frei, aber diese hier wartet in einem Netz, echt.'::text),
(295396,32822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, черепахи зазвичай плавають вільно, а ця ... в сітці, чесно.'::text,'чекає'::text,'чекає'::text,NULL::text,'Бро, черепахи зазвичай плавають вільно, а ця чекає в сітці, чесно.'::text),
(295395,32822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, las tortugas suelen nadar libres, pero esta ... en una red, en serio.'::text,'está esperando'::text,'espera'::text,NULL::text,'Tío, las tortugas suelen nadar libres, pero esta está esperando en una red, en serio.'::text),
(295394,32822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, les tortues nagent libres d''habitude, mais celle-ci ... dans un filet, sérieux.'::text,'est en train d''attendre'::text,'attend'::text,NULL::text,'Frère, les tortues nagent libres d''habitude, mais celle-ci est en train d''attendre dans un filet, sérieux.'::text),
(295397,32822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kaplumbağalar genelde özgürce yüzer ama bu bir ağda ..., cidden.'::text,'bekliyor'::text,'bekler'::text,NULL::text,'Kanka, kaplumbağalar genelde özgürce yüzer ama bu bir ağda bekliyor, cidden.'::text),
(295398,32822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a teknősök általában szabadon úsznak, de ez egy hálóban ..., komolyan.'::text,'vár'::text,'vár'::text,NULL::text,'Tesó, a teknősök általában szabadon úsznak, de ez egy hálóban vár, komolyan.'::text),
(295401,32823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Nach 5 Minuten ist die freie Schildkröte ... als die Taucher.'::text,'schneller'::text,'schneller'::text,'am schnellsten'::text,'Bericht: Nach 5 Minuten ist die freie Schildkröte schneller als die Taucher.'::text),
(295405,32823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: через 5 хвилин вільна черепаха ... за дайверів.'::text,'швидша'::text,'більш швидка'::text,'найшвидша'::text,'Звіт: через 5 хвилин вільна черепаха швидша за дайверів.'::text),
(295404,32823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: tras 5 minutos, la tortuga libre es ... que los buceadores.'::text,'más rápida'::text,'más rápida'::text,'la más rápida'::text,'Informe: tras 5 minutos, la tortuga libre es más rápida que los buceadores.'::text),
(295403,32823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : après 5 minutes, la tortue libre est ... que les plongeurs.'::text,'plus rapide'::text,'plus rapide'::text,'la plus rapide'::text,'Rapport : après 5 minutes, la tortue libre est plus rapide que les plongeurs.'::text),
(295406,32823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: 5 dakika sonra özgür kaplumbağa dalgıçlardan ...'::text,'daha hızlı'::text,'daha hızlı'::text,'en hızlı'::text,'Rapor: 5 dakika sonra özgür kaplumbağa dalgıçlardan daha hızlı.'::text),
(295407,32823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: 5 perc után a szabad teknős ... a búvároknál.'::text,'gyorsabb'::text,'gyorsabb'::text,'leggyorsabb'::text,'Jelentés: 5 perc után a szabad teknős gyorsabb a búvároknál.'::text),
(293907,32657,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr entspannend, logisch. Morgen ... er wieder schnell diese Rampe runterfahren.'::text,'wird'::text,'fährt'::text,'fuhr'::text,'Sehr entspannend, logisch. Morgen wird er wieder schnell diese Rampe runterfahren.'::text),
(293911,32657,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже розслабляє, звісно. Завтра він знову ... швидко з цієї рампи.'::text,'з''їде'::text,'з''їжджає'::text,'з''їхав'::text,'Дуже розслабляє, звісно. Завтра він знову з''їде швидко з цієї рампи.'::text),
(293910,32657,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy relajante, claro. Mañana él ... rápido por esta rampa otra vez.'::text,'bajará'::text,'baja'::text,'bajó'::text,'Muy relajante, claro. Mañana él bajará rápido por esta rampa otra vez.'::text),
(293909,32657,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très reposant, évidemment. Demain il ... encore vite cette rampe.'::text,'descendra'::text,'descend'::text,'a descendu'::text,'Très reposant, évidemment. Demain il descendra encore vite cette rampe.'::text),
(293912,32657,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok rahatlatıcı, tabii ki. Yarın yine bu rampadan hızla ...'::text,'inecek'::text,'iner'::text,'indi'::text,'Çok rahatlatıcı, tabii ki. Yarın yine bu rampadan hızla inecek.'::text),
(293913,32657,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon pihentető, persze. Holnap megint gyorsan ... ezen a rámpán.'::text,'le fog száguldani'::text,'leszáguld'::text,'leszáguldott'::text,'Nagyon pihentető, persze. Holnap megint gyorsan le fog száguldani ezen a rámpán.'::text),
(293916,32658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo Alter, er ... die Rampe so schnell runterfahren, ohne Witz.'::text,'wird'::text,'werden'::text,'wird'::text,'Yo Alter, er wird die Rampe so schnell runterfahren, ohne Witz.'::text),
(293920,32658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бро, він ... з тієї рампи так швидко, без брехні.'::text,'збирається з''їхати'::text,'збираються з''їхати'::text,'збирається з''їхати'::text,'Йо, бро, він збирається з''їхати з тієї рампи так швидко, без брехні.'::text),
(293919,32658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... esa rampa tan rápido, en serio.'::text,'va a bajar'::text,'van a bajar'::text,'va a bajar'::text,'Tío, él va a bajar esa rampa tan rápido, en serio.'::text),
(293918,32658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo frère, il ... cette rampe super vite, sans mentir.'::text,'va descendre'::text,'vont descendre'::text,'va descendre'::text,'Yo frère, il va descendre cette rampe super vite, sans mentir.'::text),
(293921,32658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o rampadan çok hızlı ..., yemin ederim.'::text,'inecek'::text,'inecekler'::text,'inecek'::text,'Kanka, o rampadan çok hızlı inecek, yemin ederim.'::text),
(293922,32658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azon a rámpán olyan gyorsan le ... menni, komolyan.'::text,'fog'::text,'fognak'::text,'fog'::text,'Tesó, azon a rámpán olyan gyorsan le fog menni, komolyan.'::text),
(293925,32659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, check mal sein Tempo, echt. Er ... den Sprung schnell nehmen.'::text,'wird'::text,'wird'::text,NULL::text,'Digga, check mal sein Tempo, echt. Er wird den Sprung schnell nehmen.'::text),
(293929,32659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, глянь на його швидкість, чесно. Він ... швидко взяти той трамплін.'::text,'збирається'::text,'буде'::text,NULL::text,'Чувак, глянь на його швидкість, чесно. Він збирається швидко взяти той трамплін.'::text),
(293928,32659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mira qué velocidad, en serio. Él ... pillar ese salto rápido.'::text,'va a'::text,NULL::text,NULL::text,'Tío, mira qué velocidad, en serio. Él va a pillar ese salto rápido.'::text),
(293927,32659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, regarde sa vitesse, sérieux. Il ... prendre ce saut à fond.'::text,'va'::text,NULL::text,NULL::text,'Mec, regarde sa vitesse, sérieux. Il va prendre ce saut à fond.'::text),
(293930,32659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hızına bak, cidden. O atlamaya hızlı ...'::text,'girecek'::text,'girecek'::text,NULL::text,'Kanka, hızına bak, cidden. O atlamaya hızlı girecek.'::text),
(293931,32659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, nézd a sebességét, komolyan. Gyorsan rá ... ugratni arra az ugróra.'::text,'fog'::text,'fog'::text,NULL::text,'Haver, nézd a sebességét, komolyan. Gyorsan rá fog ugratni arra az ugróra.'::text),
(293934,32660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel: 20 % ... fahren als der Fahrer vorne.'::text,'schneller'::text,'schneller'::text,'am schnellsten'::text,'Ziel: 20 % schneller fahren als der Fahrer vorne.'::text),
(293938,32660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль: їхати на 20 % ... за райдера попереду.'::text,'швидше'::text,'більш швидко'::text,'найшвидше'::text,'Ціль: їхати на 20 % швидше за райдера попереду.'::text),
(293937,32660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo: ir un 20 % ... que el ciclista de delante.'::text,'más rápido'::text,'más rápido'::text,'lo más rápido'::text,'Objetivo: ir un 20 % más rápido que el ciclista de delante.'::text),
(293936,32660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif : rouler 20 % ... que le rider devant.'::text,'plus vite'::text,'plus vite'::text,'le plus vite'::text,'Objectif : rouler 20 % plus vite que le rider devant.'::text),
(293939,32660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef: öndeki sürücüden %20 ... sürmek.'::text,'daha hızlı'::text,'daha hızlı'::text,'en hızlı'::text,'Hedef: öndeki sürücüden %20 daha hızlı sürmek.'::text),
(293940,32660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél: 20%-kal ... menni, mint az elöl haladó bringás.'::text,'gyorsabban'::text,'gyorsabban'::text,'leggyorsabban'::text,'Cél: 20%-kal gyorsabban menni, mint az elöl haladó bringás.'::text),
(293943,32661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschließt, dass er schnell fahren ..., weil langsam nicht schnell ist.'::text,'muss'::text,'muss'::text,'sollte'::text,'Er beschließt, dass er schnell fahren muss, weil langsam nicht schnell ist.'::text),
(293947,32661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішує, що ... їхати швидко, бо повільно — це не швидко.'::text,'мусить'::text,'має'::text,'мав би'::text,'Він вирішує, що мусить їхати швидко, бо повільно — це не швидко.'::text),
(293946,32661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decide que ... ir rápido, porque lento no es rápido.'::text,'debe'::text,'tiene que'::text,'debería'::text,'Decide que debe ir rápido, porque lento no es rápido.'::text),
(293945,32661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il décide qu''il ... rouler vite, parce que lent, ce n''est pas vite.'::text,'doit'::text,'doit'::text,'devrait'::text,'Il décide qu''il doit rouler vite, parce que lent, ce n''est pas vite.'::text),
(293948,32661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hızlı ... diye karar veriyor, çünkü yavaş, hızlı değildir.'::text,'sürmeli'::text,'sürmek zorunda'::text,'sürmeli'::text,'Hızlı sürmeli diye karar veriyor, çünkü yavaş, hızlı değildir.'::text),
(293949,32661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy dönt, hogy gyorsan ... mennie, mert a lassú nem gyors.'::text,'kell'::text,'kell'::text,'kellene'::text,'Úgy dönt, hogy gyorsan kell mennie, mert a lassú nem gyors.'::text),
(293952,32662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fährt so schnell! Er ... vor der totalen Katastrophe bremsen!'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Er fährt so schnell! Er sollte vor der totalen Katastrophe bremsen!'::text),
(293956,32662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він їде так швидко! Він ... пригальмувати до повної катастрофи!'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Він їде так швидко! Він мав би пригальмувати до повної катастрофи!'::text),
(293955,32662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Va tan rápido! ¡... frenar antes del desastre total!'::text,'Debería'::text,'Debería'::text,'Debería'::text,'¡Va tan rápido! ¡Debería frenar antes del desastre total!'::text),
(293954,32662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il roule si vite ! Il ... ralentir avant la catastrophe totale !'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Il roule si vite ! Il devrait ralentir avant la catastrophe totale !'::text),
(293957,32662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok hızlı sürüyor! Tam bir felaket olmadan önce ...!'::text,'yavaşlamalı'::text,'yavaşlamalı'::text,'yavaşlamalı'::text,'Çok hızlı sürüyor! Tam bir felaket olmadan önce yavaşlamalı!'::text),
(293958,32662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan gyorsan megy! Le ... lassítania a totális katasztrófa előtt!'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Olyan gyorsan megy! Le kellene lassítania a totális katasztrófa előtt!'::text),
(300126,33348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, deine Decke hat ... riesiges Loch und du bleibst so cool.'::text,'ein'::text,'ein'::text,'das'::text,'Ehrlich, deine Decke hat ein riesiges Loch und du bleibst so cool.'::text),
(300130,33348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у твоїй стелі ... величезна діра, а ти лишаєшся таким спокійним.'::text,''::text,NULL::text,NULL::text,'Чесно, у твоїй стелі величезна діра, а ти лишаєшся таким спокійним.'::text),
(300129,33348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tu techo tiene ... agujero enorme y tú te quedas tan tranquilo.'::text,'un'::text,'un'::text,'el'::text,'Sinceramente, tu techo tiene un agujero enorme y tú te quedas tan tranquilo.'::text),
(300128,33348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ton plafond a ... énorme trou et tu restes super cool.'::text,'un'::text,'un'::text,'le'::text,'Franchement, ton plafond a un énorme trou et tu restes super cool.'::text),
(300131,33348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, tavanında ... kocaman delik var ve sen hâlâ çok sakinsin.'::text,'bir'::text,'bir'::text,NULL::text,'Açıkçası, tavanında bir kocaman delik var ve sen hâlâ çok sakinsin.'::text),
(300132,33348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a plafonodon ... hatalmas lyuk van, te meg olyan laza maradsz.'::text,'egy'::text,'egy'::text,'a'::text,'Őszintén, a plafonodon egy hatalmas lyuk van, te meg olyan laza maradsz.'::text),
(300135,33349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du stehst neben ... und bleibst cool, ehrlich.'::text,'diesen Löchern'::text,'diesem Loch'::text,'diesen Löchern'::text,'Du stehst neben diesen Löchern und bleibst cool, ehrlich.'::text),
(300139,33349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти стоїш біля ... і лишаєшся спокійним, чесно.'::text,'цих дір'::text,'цих дір'::text,'цієї діри'::text,'Ти стоїш біля цих дір і лишаєшся спокійним, чесно.'::text),
(300138,33349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estás de pie junto a ... y te quedas tan tranquilo, en serio.'::text,'estos agujeros'::text,'este agujero'::text,'estos agujeros'::text,'Estás de pie junto a estos agujeros y te quedas tan tranquilo, en serio.'::text),
(300137,33349,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu es debout à côté de ... et tu restes cool, franchement.'::text,'ces trous'::text,'ce trou'::text,'ces trous'::text,'Tu es debout à côté de ces trous et tu restes cool, franchement.'::text),
(300140,33349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yanında duruyorsun ve sakin kalıyorsun, açıkçası.'::text,'Bu deliklerin'::text,'Bu deliklerin'::text,'Bu deliğin'::text,'Bu deliklerin yanında duruyorsun ve sakin kalıyorsun, açıkçası.'::text),
(300141,33349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ott állsz ..., és laza maradsz, őszintén.'::text,'ezek mellett a lyukak mellett'::text,'emellett a lyuk mellett'::text,'ezek mellett a lyukak mellett'::text,'Ott állsz ezek mellett a lyukak mellett, és laza maradsz, őszintén.'::text),
(300153,33351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ist ein großes Loch ... der Decke.'::text,'in'::text,'auf'::text,'an'::text,'Da ist ein großes Loch in der Decke.'::text),
(300157,33351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велика діра ... стелі.'::text,'у'::text,'на'::text,'біля'::text,'Велика діра у стелі.'::text),
(300156,33351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hay un agujero grande ... el techo.'::text,'en'::text,'sobre'::text,'a'::text,'Hay un agujero grande en el techo.'::text),
(300155,33351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a un gros trou ... le plafond.'::text,'dans'::text,'sur'::text,'à'::text,'Il y a un gros trou dans le plafond.'::text),
(300158,33351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavanın ... büyük bir delik var.'::text,'içinde'::text,'üstünde'::text,NULL::text,'Tavanın içinde büyük bir delik var.'::text),
(300159,33351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagy lyuk van a ...'::text,'plafonban'::text,'plafonon'::text,'plafonnál'::text,'Nagy lyuk van a plafonban.'::text),
(300162,33352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Feder macht ... Löcher, eins oben und eins unten.'::text,'zwei'::text,'zweite'::text,'zweimal'::text,'Die Feder macht zwei Löcher, eins oben und eins unten.'::text),
(300166,33352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пружина робить ... діри, одну вгорі й одну внизу.'::text,'дві'::text,'другу'::text,'двічі'::text,'Пружина робить дві діри, одну вгорі й одну внизу.'::text),
(300165,33352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El muelle hace ... agujeros, uno arriba y otro abajo.'::text,'dos'::text,'segundo'::text,'dos veces'::text,'El muelle hace dos agujeros, uno arriba y otro abajo.'::text),
(300164,33352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le ressort fait ... trous, un en haut et un en bas.'::text,'deux'::text,'deuxième'::text,'deux fois'::text,'Le ressort fait deux trous, un en haut et un en bas.'::text),
(300167,33352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yay ... delik açıyor, biri yukarıda biri aşağıda.'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'Yay iki delik açıyor, biri yukarıda biri aşağıda.'::text),
(300168,33352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rugó ... lyukat üt, egyet fent és egyet lent.'::text,'két'::text,'második'::text,'kétszer'::text,'A rugó két lyukat üt, egyet fent és egyet lent.'::text),
(300180,33354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reparaturbudget: 900 Euro, weil in diesem Zimmer ... Löcher sind.'::text,'einige'::text,'irgendwelche'::text,'viel'::text,'Reparaturbudget: 900 Euro, weil in diesem Zimmer einige Löcher sind.'::text),
(300184,33354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет на ремонт: 900 євро, бо в цій кімнаті є ... діри.'::text,'деякі'::text,'будь-які'::text,'багато'::text,'Бюджет на ремонт: 900 євро, бо в цій кімнаті є деякі діри.'::text),
(300183,33354,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto de reparación: 900 euros, porque hay ... agujeros en esta habitación.'::text,'algunos'::text,'cualquier'::text,'mucho'::text,'Presupuesto de reparación: 900 euros, porque hay algunos agujeros en esta habitación.'::text),
(300182,33354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget réparation : 900 euros, parce qu''il y a ... trous dans cette pièce.'::text,'des'::text,'n''importe quels'::text,'beaucoup de'::text,'Budget réparation : 900 euros, parce qu''il y a des trous dans cette pièce.'::text),
(300185,33354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamir bütçesi: 900 euro, çünkü bu odada ... delik var.'::text,'birkaç'::text,'herhangi bir'::text,'çok'::text,'Tamir bütçesi: 900 euro, çünkü bu odada birkaç delik var.'::text),
(300186,33354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Javítási keret: 900 euró, mert ebben a szobában van ... lyuk.'::text,'néhány'::text,'bármilyen'::text,'sok'::text,'Javítási keret: 900 euró, mert ebben a szobában van néhány lyuk.'::text),
(300189,33355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... ein Loch in der Decke, weil die Feder ein Loch gemacht hat.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist ein Loch in der Decke, weil die Feder ein Loch gemacht hat.'::text),
(300193,33355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У стелі ... діра, бо пружина зробила діру.'::text,'є'::text,'є'::text,'бути'::text,'У стелі є діра, бо пружина зробила діру.'::text),
(300192,33355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un agujero en el techo porque el muelle hizo un agujero.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay un agujero en el techo porque el muelle hizo un agujero.'::text),
(300191,33355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un trou dans le plafond parce que le ressort a fait un trou.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a un trou dans le plafond parce que le ressort a fait un trou.'::text),
(300194,33355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavanda bir delik ... çünkü yay bir delik açtı.'::text,'var'::text,'var'::text,'olmak'::text,'Tavanda bir delik var çünkü yay bir delik açtı.'::text),
(300195,33355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A plafonon ... egy lyuk, mert a rugó csinált egy lyukat.'::text,'van'::text,'vannak'::text,'lenni'::text,'A plafonon van egy lyuk, mert a rugó csinált egy lyukat.'::text),
(316182,35132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pure Magie! Die Artistin ... dem Publikum einen riesigen Schweif!'::text,'zeigt'::text,'zeigt'::text,'zeigt'::text,'Pure Magie! Die Artistin zeigt dem Publikum einen riesigen Schweif!'::text),
(316186,35132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжня магія! Артистка ... публіці величезний хвіст!'::text,'показує'::text,'показує'::text,'показує'::text,'Справжня магія! Артистка показує публіці величезний хвіст!'::text),
(316185,35132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pura magia! ¡La artista le ... al público una cola gigante!'::text,'está enseñando'::text,'enseña'::text,'está enseñando'::text,'¡Pura magia! ¡La artista le está enseñando al público una cola gigante!'::text),
(316184,35132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De la pure magie ! L''artiste ... au public une queue géante !'::text,'est en train de montrer'::text,'montre'::text,'est en train de montrer'::text,'De la pure magie ! L''artiste est en train de montrer au public une queue géante !'::text),
(316187,35132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir sihir! Sanatçı seyirciye dev bir kuyruk ...!'::text,'gösteriyor'::text,'gösterir'::text,'gösteriyor'::text,'Tam bir sihir! Sanatçı seyirciye dev bir kuyruk gösteriyor!'::text),
(316188,35132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiszta varázslat! Az artista egy óriási farkat ... a közönségnek!'::text,'mutat'::text,'mutat'::text,'mutat'::text,'Tiszta varázslat! Az artista egy óriási farkat mutat a közönségnek!'::text),
(316191,35133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich jongliert sie sonst, aber heute Abend ... sie einen Pfauenschweif.'::text,'zeigt'::text,'zeigt'::text,NULL::text,'Mädel, angeblich jongliert sie sonst, aber heute Abend zeigt sie einen Pfauenschweif.'::text),
(316195,35133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона зазвичай жонглює, а сьогодні ввечері ... павиний хвіст.'::text,'показує'::text,'показує'::text,NULL::text,'Подруго, кажуть, вона зазвичай жонглює, а сьогодні ввечері показує павиний хвіст.'::text),
(316194,35133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, dicen que normalmente hace malabares, pero esta noche ... una cola de pavo real.'::text,'está enseñando'::text,'enseña'::text,NULL::text,'Tía, dicen que normalmente hace malabares, pero esta noche está enseñando una cola de pavo real.'::text),
(316193,35133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît qu''elle jongle d''habitude, mais ce soir elle ... une queue de paon.'::text,'est en train de montrer'::text,'montre'::text,NULL::text,'Meuf, il paraît qu''elle jongle d''habitude, mais ce soir elle est en train de montrer une queue de paon.'::text),
(316196,35133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, genelde jonglörlük yapıyormuş ama bu akşam bir tavus kuşu kuyruğu ...'::text,'gösteriyor'::text,'gösterir'::text,NULL::text,'Kızım, genelde jonglörlük yapıyormuş ama bu akşam bir tavus kuşu kuyruğu gösteriyor.'::text),
(316197,35133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondják, általában zsonglőrködik, de ma este egy pávafarkat ...'::text,'mutat'::text,'mutat'::text,NULL::text,'Csajszi, azt mondják, általában zsonglőrködik, de ma este egy pávafarkat mutat.'::text),
