(316227,35137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Show ist zum Zeigen da, also ... sie dem Publikum etwas zeigen.'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Die Show ist zum Zeigen da, also muss sie dem Publikum etwas zeigen.'::text),
