(300974,33442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment une voiture de rêve : un jour, elle ..., dit son mari.'::text,'l''adorera'::text,'l''adore'::text,'l''a adorée'::text,'Évidemment une voiture de rêve : un jour, elle l''adorera, dit son mari.'::text),
