(300978,33442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, álomautó: egy nap ..., mondja a férje.'::text,'imádni fogja'::text,'imádja'::text,'imádta'::text,'Persze, álomautó: egy nap imádni fogja, mondja a férje.'::text),
(300981,33443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ihr Mann ... mit diesem winzigen Auto überall hinfahren, ohne Witz.'::text,'wird'::text,'werden'::text,'wird'::text,'Alter, ihr Mann wird mit diesem winzigen Auto überall hinfahren, ohne Witz.'::text),
(300985,33443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, її чоловік ... цією крихітною машиною всюди, без брехні.'::text,'збирається їздити'::text,'збираються їздити'::text,'збирається їздити'::text,'Бро, її чоловік збирається їздити цією крихітною машиною всюди, без брехні.'::text),
(300984,33443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, su marido ... ese coche diminuto a todas partes, en serio.'::text,'va a llevar'::text,'van a llevar'::text,'va a llevar'::text,'Tío, su marido va a llevar ese coche diminuto a todas partes, en serio.'::text),
(300983,33443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, son mari ... cette minuscule voiture partout, sans mentir.'::text,'va conduire'::text,'vont conduire'::text,'va conduire'::text,'Frère, son mari va conduire cette minuscule voiture partout, sans mentir.'::text),
(300986,33443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kocası o minicik arabayı her yere ..., yemin ederim.'::text,'sürecek'::text,'sürecekler'::text,'sürecek'::text,'Kanka, kocası o minicik arabayı her yere sürecek, yemin ederim.'::text),
(300987,33443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a férje mindenhova azzal a pici autóval ... járni, komolyan.'::text,'fog'::text,'fognak'::text,'fog'::text,'Tesó, a férje mindenhova azzal a pici autóval fog járni, komolyan.'::text),
(300999,33445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Mann hat eine Menge ... in dem winzigen Auto.'::text,'Spaß'::text,'Spaß'::text,'einen Spaß'::text,'Ihr Mann hat eine Menge Spaß in dem winzigen Auto.'::text),
(301003,33445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її чоловіка багато ... в крихітній машині.'::text,'веселощів'::text,'веселощів'::text,'веселощів'::text,'У її чоловіка багато веселощів в крихітній машині.'::text),
(301002,33445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su marido tiene mucha ... en el coche diminuto.'::text,'diversión'::text,'diversión'::text,'una diversión'::text,'Su marido tiene mucha diversión en el coche diminuto.'::text),
(301001,33445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son mari a beaucoup de ... dans la minuscule voiture.'::text,'plaisir'::text,'plaisir'::text,'un plaisir'::text,'Son mari a beaucoup de plaisir dans la minuscule voiture.'::text),
(301004,33445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kocası minicik arabada bol bol ... yaşıyor.'::text,'eğlence'::text,'eğlenceler'::text,'bir eğlence'::text,'Kocası minicik arabada bol bol eğlence yaşıyor.'::text),
(301005,33445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férjének sok ... jut a pici autóban.'::text,'móka'::text,'móka'::text,'egy móka'::text,'A férjének sok móka jut a pici autóban.'::text),
(301008,33446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist ihr Mann, also sind ... anderen Ehemänner im Auto.'::text,'keine'::text,'viel'::text,'einige'::text,'Er ist ihr Mann, also sind keine anderen Ehemänner im Auto.'::text),
(301012,33446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він її чоловік, тож в авто немає ... інших чоловіків.'::text,'жодних'::text,'багато'::text,'деяких'::text,'Він її чоловік, тож в авто немає жодних інших чоловіків.'::text),
(301011,33446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él es su marido, así que no hay ... otro marido en el coche.'::text,'ningún'::text,'mucho'::text,'algunos'::text,'Él es su marido, así que no hay ningún otro marido en el coche.'::text),
(301010,33446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est son mari, donc il n''y a ... autre mari dans la voiture.'::text,'aucun'::text,'beaucoup d'''::text,'des'::text,'C''est son mari, donc il n''y a aucun autre mari dans la voiture.'::text),
(301013,33446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O onun kocası, bu yüzden arabada ... başka koca yok.'::text,'hiç'::text,'çok'::text,'biraz'::text,'O onun kocası, bu yüzden arabada hiç başka koca yok.'::text),
(301014,33446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a férje, tehát nincs ... más férj az autóban.'::text,'semmilyen'::text,'sok'::text,'néhány'::text,'Ő a férje, tehát nincs semmilyen más férj az autóban.'::text),
(301017,33447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... große Worte auf dem Auto: „Ich bin ihr Mann.“'::text,'sind'::text,'ist'::text,'sein'::text,'Okay, also angeblich sind große Worte auf dem Auto: „Ich bin ihr Mann.“'::text),
(301021,33447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, на машині ... великі слова: «Я її чоловік».'::text,'є'::text,'є'::text,'бути'::text,'Короче, кажуть, на машині є великі слова: «Я її чоловік».'::text),
(301020,33447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, se supone que ... unas letras grandes en el coche: «Soy su marido».'::text,'hay'::text,'hay'::text,'hay'::text,'A ver, se supone que hay unas letras grandes en el coche: «Soy su marido».'::text),
(301019,33447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, soi-disant ... de grandes lettres sur la voiture : « Je suis son mari. »'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Bon alors, soi-disant il y a de grandes lettres sur la voiture : « Je suis son mari. »'::text),
(301022,33447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, güya arabada büyük harflerle yazı ...: “Ben onun kocasıyım.”'::text,'var'::text,'var'::text,'olmak'::text,'Tamam yani, güya arabada büyük harflerle yazı var: “Ben onun kocasıyım.”'::text),
(301023,33447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag nagy betűs szavak ... az autón: „A férje vagyok.”'::text,'vannak'::text,'van'::text,'lenni'::text,'Szóval, állítólag nagy betűs szavak vannak az autón: „A férje vagyok.”'::text),
(301521,33503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die graue Taube ... Schmuck, weil''s cool ist.'::text,'trägt'::text,'tragen'::text,'tragend'::text,'Alter, die graue Taube trägt Schmuck, weil''s cool ist.'::text),
(301525,33503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, сірий голуб ... прикраси, бо це круто.'::text,'носить'::text,'носити'::text,'носячи'::text,'Бро, сірий голуб носить прикраси, бо це круто.'::text),
(301524,33503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la paloma gris ... joyas porque es guay.'::text,'lleva'::text,'llevar'::text,'llevando'::text,'Tío, la paloma gris lleva joyas porque es guay.'::text),
(301523,33503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le pigeon gris ... des bijoux parce que c''est cool.'::text,'porte'::text,'porter'::text,'portant'::text,'Frère, le pigeon gris porte des bijoux parce que c''est cool.'::text),
(301526,33503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gri güvercin takı ... çünkü havalı.'::text,'takar'::text,'takmak'::text,'takarak'::text,'Kanka, gri güvercin takı takar çünkü havalı.'::text),
(301527,33503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a szürke galamb ékszert ..., mert menő.'::text,'hord'::text,'hordani'::text,'hordó'::text,'Tesó, a szürke galamb ékszert hord, mert menő.'::text),
(301530,33504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, nicht jede Taube ... solchen Schmuck tragen.'::text,'kann'::text,'kann'::text,NULL::text,'Nee Alter, nicht jede Taube kann solchen Schmuck tragen.'::text),
(301534,33504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, не кожен голуб ... носити такі прикраси.'::text,'може'::text,'може'::text,NULL::text,'Не, бро, не кожен голуб може носити такі прикраси.'::text),
(301533,33504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, no todas las palomas ... llevar joyas así.'::text,'pueden'::text,'pueden'::text,NULL::text,'Qué va, tío, no todas las palomas pueden llevar joyas así.'::text),
(301532,33504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, tous les pigeons ne ... pas porter des bijoux comme ça.'::text,'peuvent'::text,'peuvent'::text,NULL::text,'Non frère, tous les pigeons ne peuvent pas porter des bijoux comme ça.'::text),
(301535,33504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, her güvercin böyle takılar ...'::text,'takamaz'::text,'takamaz'::text,NULL::text,'Yok kanka, her güvercin böyle takılar takamaz.'::text),
(301536,33504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, nem minden galamb ... ilyen ékszert hordani.'::text,'tud'::text,'tud'::text,NULL::text,'Á, tesó, nem minden galamb tud ilyen ékszert hordani.'::text),
(301539,33505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schmuckbericht: Der Laden verkauft ... am Tag.'::text,'20 Ringe'::text,'20 Ring'::text,'20 Ringe'::text,'Schmuckbericht: Der Laden verkauft 20 Ringe am Tag.'::text),
(301543,33505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт про прикраси: магазин продає ... на день.'::text,'20 каблучок'::text,'20 каблучка'::text,'20 каблучок'::text,'Звіт про прикраси: магазин продає 20 каблучок на день.'::text),
(301542,33505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe de joyería: la tienda vende ... al día.'::text,'20 anillos'::text,'20 anillo'::text,'20 anillos'::text,'Informe de joyería: la tienda vende 20 anillos al día.'::text),
(301541,33505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport bijoux : la boutique vend ... par jour.'::text,'20 bagues'::text,'20 bague'::text,'20 bagues'::text,'Rapport bijoux : la boutique vend 20 bagues par jour.'::text),
(301544,33505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takı raporu: dükkân günde ... satıyor.'::text,'20 yüzük'::text,'20 yüzük'::text,'20 yüzükler'::text,'Takı raporu: dükkân günde 20 yüzük satıyor.'::text),
(301545,33505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ékszerjelentés: a bolt naponta ... ad el.'::text,'20 gyűrűt'::text,'20 gyűrűt'::text,'20 gyűrűt'::text,'Ékszerjelentés: a bolt naponta 20 gyűrűt ad el.'::text),
(301548,33506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Dieser pinke Ring ist ... teures Schmuckstück!'::text,'ein'::text,'ein'::text,'das'::text,'Unglaublich! Dieser pinke Ring ist ein teures Schmuckstück!'::text),
(301552,33506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Ця рожева каблучка — ... дорога прикраса!'::text,''::text,NULL::text,NULL::text,'Неймовірно! Ця рожева каблучка — дорога прикраса!'::text),
(301551,33506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡Este anillo rosa es ... joya cara!'::text,'una'::text,'una'::text,'la'::text,'¡Increíble! ¡Este anillo rosa es una joya cara!'::text),
(301550,33506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Cette bague rose est ... bijou cher !'::text,'un'::text,'un'::text,'le'::text,'Incroyable ! Cette bague rose est un bijou cher !'::text),
(301553,33506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Bu pembe yüzük ... pahalı mücevher!'::text,'bir'::text,'bir'::text,NULL::text,'İnanılmaz! Bu pembe yüzük bir pahalı mücevher!'::text),
(301554,33506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! Ez a rózsaszín gyűrű ... drága ékszer!'::text,'egy'::text,'egy'::text,'a'::text,'Hihetetlen! Ez a rózsaszín gyűrű egy drága ékszer!'::text),
(301557,33507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand sagt mir was! Ich ... diesen Schmuck für immer tragen!'::text,'muss'::text,'muss'::text,'sollte'::text,'Niemand sagt mir was! Ich muss diesen Schmuck für immer tragen!'::text),
(301561,33507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мені ніхто не каже! Я ... носити ці прикраси вічно!'::text,'мушу'::text,'маю'::text,'мав би'::text,'Мені ніхто не каже! Я мушу носити ці прикраси вічно!'::text),
(301560,33507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nadie me dice nada! ¡... llevar estas joyas para siempre!'::text,'Debo'::text,'Tengo que'::text,'Debería'::text,'¡Nadie me dice nada! ¡Debo llevar estas joyas para siempre!'::text),
(301559,33507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne me dit rien ! Je ... porter ces bijoux pour toujours !'::text,'dois'::text,'dois'::text,'devrais'::text,'Personne ne me dit rien ! Je dois porter ces bijoux pour toujours !'::text),
(301562,33507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse bana söylemiyor! Bu takıları sonsuza dek ...!'::text,'takmalıyım'::text,'takmak zorundayım'::text,'takmalıyım'::text,'Kimse bana söylemiyor! Bu takıları sonsuza dek takmalıyım!'::text),
(301563,33507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki nem szól nekem! Örökké ... hordanom ezt az ékszert!'::text,'kell'::text,'kell'::text,'kellene'::text,'Senki nem szól nekem! Örökké kell hordanom ezt az ékszert!'::text),
(301566,33508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die riesige Taube will den Schmuck! Du ... ihn verstecken!'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Katastrophe! Die riesige Taube will den Schmuck! Du solltest ihn verstecken!'::text),
(301570,33508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Величезний голуб хоче прикраси! Ти ... їх сховати!'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Катастрофа! Величезний голуб хоче прикраси! Ти мав би їх сховати!'::text),
(301569,33508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡La paloma enorme quiere las joyas! ¡... esconderlas!'::text,'Deberías'::text,'Deberías'::text,'Deberías'::text,'¡Desastre! ¡La paloma enorme quiere las joyas! ¡Deberías esconderlas!'::text),
(301568,33508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cata ! L''énorme pigeon veut les bijoux ! Tu ... les cacher !'::text,'devrais'::text,'devrais'::text,'devrais'::text,'La cata ! L''énorme pigeon veut les bijoux ! Tu devrais les cacher !'::text),
(301571,33508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Dev güvercin takıları istiyor! Onları ...!'::text,'saklamalısın'::text,'saklamalısın'::text,'saklamalısın'::text,'Felaket! Dev güvercin takıları istiyor! Onları saklamalısın!'::text),
(301572,33508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Az óriási galamb akarja az ékszert! El ... rejtened!'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Katasztrófa! Az óriási galamb akarja az ékszert! El kellene rejtened!'::text),
(323724,35970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Touristen ... keine Karte, und es ist Nacht!'::text,'haben'::text,'hat'::text,'haben'::text,'Katastrophe! Die Touristen haben keine Karte, und es ist Nacht!'::text),
(323728,35970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Туристи не ... жодної мапи, а зараз ніч!'::text,'мають'::text,'має'::text,'мають'::text,'Катастрофа! Туристи не мають жодної мапи, а зараз ніч!'::text),
(323727,35970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Los turistas no ... mapa, y es de noche!'::text,'tienen'::text,'tiene'::text,'tienen'::text,'¡Desastre! ¡Los turistas no tienen mapa, y es de noche!'::text),
(323726,35970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cata ! Les touristes ... pas de carte, et il fait nuit !'::text,'n''ont'::text,'n''a'::text,'n''ont'::text,'La cata ! Les touristes n''ont pas de carte, et il fait nuit !'::text),
(323729,35970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Turistlerin haritası ... ve gece oldu!'::text,'yok'::text,'yok'::text,'yok'::text,'Felaket! Turistlerin haritası yok ve gece oldu!'::text),
(323730,35970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A turistáknak ... térképük, és éjszaka van!'::text,'nincs'::text,'nincs'::text,'nincs'::text,'Katasztrófa! A turistáknak nincs térképük, és éjszaka van!'::text),
(323733,35971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Jeder Tourist ... hier einen Strohhut!'::text,'kauft'::text,'kaufen'::text,'kaufend'::text,'Albtraum! Jeder Tourist kauft hier einen Strohhut!'::text),
(323737,35971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Кожен турист тут ... солом''яний капелюх!'::text,'купує'::text,'купувати'::text,'купуючи'::text,'Жах! Кожен турист тут купує солом''яний капелюх!'::text),
(323736,35971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Aquí cada turista ... un sombrero de paja!'::text,'compra'::text,'comprar'::text,'comprando'::text,'¡Pesadilla! ¡Aquí cada turista compra un sombrero de paja!'::text),
(323735,35971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Chaque touriste ... un chapeau de paille ici !'::text,'achète'::text,'acheter'::text,'achetant'::text,'Cauchemar ! Chaque touriste achète un chapeau de paille ici !'::text),
(323738,35971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Burada her turist hasır şapka ...!'::text,'alır'::text,'almak'::text,'alarak'::text,'Kâbus! Burada her turist hasır şapka alır!'::text),
(323739,35971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Itt minden turista ... egy szalmakalapot!'::text,'vesz'::text,'venni'::text,'vevő'::text,'Rémálom! Itt minden turista vesz egy szalmakalapot!'::text),
(323742,35972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! ... die Touristen ihr Hotel im Dunkeln finden?'::text,'Können'::text,'Können'::text,'Sind'::text,'Katastrophe! Können die Touristen ihr Hotel im Dunkeln finden?'::text),
(323746,35972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Чи ... туристи знайти свій готель у темряві?'::text,'можуть'::text,'можуть'::text,'є'::text,'Катастрофа! Чи можуть туристи знайти свій готель у темряві?'::text),
(323745,35972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¿... los turistas encontrar su hotel a oscuras?'::text,'Pueden'::text,'Pueden'::text,'Están'::text,'¡Desastre! ¿Pueden los turistas encontrar su hotel a oscuras?'::text),
(323744,35972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cata ! Est-ce que les touristes ... trouver leur hôtel dans le noir ?'::text,'peuvent'::text,'peuvent'::text,'sont'::text,'La cata ! Est-ce que les touristes peuvent trouver leur hôtel dans le noir ?'::text),
(323747,35972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Turistler karanlıkta otellerini ... mi?'::text,'bulabilirler'::text,'bulabilirler'::text,NULL::text,'Felaket! Turistler karanlıkta otellerini bulabilirler mi?'::text),
(323748,35972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! ... a turisták megtalálni a szállodájukat a sötétben?'::text,'Tudják'::text,'Tudják'::text,'Vannak'::text,'Katasztrófa! Tudják a turisták megtalálni a szállodájukat a sötétben?'::text),
(323751,35973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei ... spazieren nachts die Promenade entlang.'::text,'Touristen'::text,'Tourist'::text,'Touristen'::text,'Zwei Touristen spazieren nachts die Promenade entlang.'::text),
(323755,35973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє ... гуляють уночі набережною.'::text,'туристів'::text,'турист'::text,'туристів'::text,'Двоє туристів гуляють уночі набережною.'::text),
(323754,35973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos ... pasean por el paseo marítimo de noche.'::text,'turistas'::text,'turista'::text,'turistas'::text,'Dos turistas pasean por el paseo marítimo de noche.'::text),
(323753,35973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux ... se promènent sur la promenade la nuit.'::text,'touristes'::text,'touriste'::text,'touristes'::text,'Deux touristes se promènent sur la promenade la nuit.'::text),
(323756,35973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki ... gece sahil yolunda yürüyor.'::text,'turist'::text,'turist'::text,'turistler'::text,'İki turist gece sahil yolunda yürüyor.'::text),
(323757,35973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ... sétál éjjel a sétányon.'::text,'turista'::text,'turista'::text,'turista'::text,'Két turista sétál éjjel a sétányon.'::text),
(323769,35975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Touristen gehen an den Sonnenhüten vorbei.'::text,'Diese'::text,'Dieser'::text,'Jener'::text,'Diese Touristen gehen an den Sonnenhüten vorbei.'::text),
(323773,35975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... туристи проходять повз капелюхи від сонця.'::text,'Ці'::text,'Цей'::text,'Той'::text,'Ці туристи проходять повз капелюхи від сонця.'::text),
(323772,35975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... turistas pasan junto a los sombreros de sol.'::text,'Estos'::text,'Este'::text,'Ese'::text,'Estos turistas pasan junto a los sombreros de sol.'::text),
(323771,35975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... touristes passent devant les chapeaux de soleil.'::text,'Ces'::text,'Ce'::text,'Ce'::text,'Ces touristes passent devant les chapeaux de soleil.'::text),
(323774,35975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... turistler güneş şapkalarının önünden geçiyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu turistler güneş şapkalarının önünden geçiyor.'::text),
(323775,35975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a turisták elsétálnak a napkalapok mellett.'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Ezek a turisták elsétálnak a napkalapok mellett.'::text),
(323778,35976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Tourist legt ... Arm um ihre Schultern.'::text,'seinen'::text,'ihren'::text,'seinen'::text,'Der Tourist legt seinen Arm um ihre Schultern.'::text),
(323782,35976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Турист кладе ... руку їй на плечі.'::text,'свою'::text,'свою'::text,'свою'::text,'Турист кладе свою руку їй на плечі.'::text),
(323781,35976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El turista le pasa ... brazo por los hombros.'::text,'su'::text,'su'::text,'su'::text,'El turista le pasa su brazo por los hombros.'::text),
(323780,35976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le touriste passe ... bras autour de ses épaules.'::text,'son'::text,'son'::text,'son'::text,'Le touriste passe son bras autour de ses épaules.'::text),
(323783,35976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turist ... kolunu onun omuzlarına atıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Turist onun kolunu onun omuzlarına atıyor.'::text),
(323784,35976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A turista a ... a lány vállára teszi.'::text,'karját'::text,'karját'::text,'karját'::text,'A turista a karját a lány vállára teszi.'::text),
(317370,35264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Auto ... so klein, und du fährst es mit Stil.'::text,'ist'::text,'sind'::text,'bin'::text,'Ehrlich, dein Auto ist so klein, und du fährst es mit Stil.'::text),
(317374,35264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твоя машина ... така маленька, а ти водиш її зі стилем.'::text,'є'::text,'є'::text,'є'::text,'Чесно, твоя машина є така маленька, а ти водиш її зі стилем.'::text),
(317373,35264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tu coche ... tan pequeño, y lo conduces con estilo.'::text,'es'::text,'son'::text,'soy'::text,'Sinceramente, tu coche es tan pequeño, y lo conduces con estilo.'::text),
(317372,35264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ta voiture ... si petite, et tu la conduis avec style.'::text,'est'::text,'sont'::text,'suis'::text,'Franchement, ta voiture est si petite, et tu la conduis avec style.'::text),
(317375,35264,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, araban çok küçük ... ve onu tarzla sürüyorsun.'::text,''::text,NULL::text,NULL::text,'Açıkçası, araban çok küçük ve onu tarzla sürüyorsun.'::text),
(317376,35264,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az autód ... olyan kicsi, és stílusosan vezeted.'::text,''::text,NULL::text,'vagyok'::text,'Őszintén, az autód olyan kicsi, és stílusosan vezeted.'::text),
(317397,35267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein großes Auto: Er ... das kleine Auto normalerweise von Hand raus.'::text,'schiebt'::text,'schob'::text,NULL::text,'Eindeutig ein großes Auto: Er schiebt das kleine Auto normalerweise von Hand raus.'::text),
(317401,35267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно велика машина: він зазвичай ... маленьку машину вручну.'::text,'виштовхує'::text,'виштовхував'::text,NULL::text,'Явно велика машина: він зазвичай виштовхує маленьку машину вручну.'::text),
(317400,35267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clarísimamente un coche grande: normalmente él ... el coche pequeño hacia fuera a mano.'::text,'empuja'::text,'empujó'::text,NULL::text,'Clarísimamente un coche grande: normalmente él empuja el coche pequeño hacia fuera a mano.'::text),
(317399,35267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement une grosse voiture : d''habitude, il ... la petite voiture dehors à la main.'::text,'pousse'::text,'a poussé'::text,NULL::text,'Clairement une grosse voiture : d''habitude, il pousse la petite voiture dehors à la main.'::text),
(317402,35267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki büyük bir araba: küçük arabayı genelde elle dışarı ...'::text,'iter'::text,'itti'::text,NULL::text,'Belli ki büyük bir araba: küçük arabayı genelde elle dışarı iter.'::text),
(317403,35267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen nagy autó: általában kézzel ... ki a kis autót.'::text,'tolja'::text,'tolta'::text,NULL::text,'Egyértelműen nagy autó: általában kézzel tolja ki a kis autót.'::text),
(317406,35268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade jetzt ... der Mann das kleine Auto raus.'::text,'schiebt'::text,'schiebt'::text,'schiebt'::text,'Gerade jetzt schiebt der Mann das kleine Auto raus.'::text),
(317410,35268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз чоловік ... маленьку машину.'::text,'виштовхує'::text,'виштовхує'::text,'виштовхує'::text,'Саме зараз чоловік виштовхує маленьку машину.'::text),
(317409,35268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el hombre ... el coche pequeño hacia fuera.'::text,'está empujando'::text,'empuja'::text,'está empujando'::text,'Ahora mismo el hombre está empujando el coche pequeño hacia fuera.'::text),
(317408,35268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''homme ... la petite voiture dehors.'::text,'est en train de pousser'::text,'pousse'::text,'est en train de pousser'::text,'En ce moment, l''homme est en train de pousser la petite voiture dehors.'::text),
(317411,35268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an adam küçük arabayı dışarı ...'::text,'itiyor'::text,'iter'::text,'itiyor'::text,'Şu an adam küçük arabayı dışarı itiyor.'::text),
(317412,35268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most épp a férfi ... ki a kis autót.'::text,'tolja'::text,'tolja'::text,'tolja'::text,'Most épp a férfi tolja ki a kis autót.'::text),
(317415,35269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fährt normalerweise ein großes Auto, aber heute ... er ein kleines.'::text,'fährt'::text,'fährt'::text,NULL::text,'Er fährt normalerweise ein großes Auto, aber heute fährt er ein kleines.'::text),
(317419,35269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зазвичай їздить на великій машині, а сьогодні ... на маленькій.'::text,'їздить'::text,'їздить'::text,NULL::text,'Він зазвичай їздить на великій машині, а сьогодні їздить на маленькій.'::text),
