(317417,35269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il conduit une grosse voiture, mais aujourd''hui il ... une petite.'::text,'est en train de conduire'::text,'conduit'::text,NULL::text,'D''habitude il conduit une grosse voiture, mais aujourd''hui il est en train de conduire une petite.'::text),
(317420,35269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde büyük bir araba sürer ama bugün küçük bir tane ...'::text,'sürüyor'::text,'sürer'::text,NULL::text,'Genelde büyük bir araba sürer ama bugün küçük bir tane sürüyor.'::text),
(317421,35269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában nagy autót vezet, de ma egy kicsit ...'::text,'vezet'::text,'vezet'::text,NULL::text,'Általában nagy autót vezet, de ma egy kicsit vezet.'::text),
(317424,35270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Auto ist ... als die SUVs da, und ehrlich, das ist cool.'::text,'kleiner'::text,'kleiner'::text,'am kleinsten'::text,'Dein Auto ist kleiner als die SUVs da, und ehrlich, das ist cool.'::text),
(317428,35270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоя машина ... за ті позашляховики, і чесно, це круто.'::text,'менша'::text,'більш маленька'::text,'найменша'::text,'Твоя машина менша за ті позашляховики, і чесно, це круто.'::text),
(317427,35270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu coche es ... que esos SUV, y sinceramente, eso es guay.'::text,'más pequeño'::text,'más pequeño'::text,'el más pequeño'::text,'Tu coche es más pequeño que esos SUV, y sinceramente, eso es guay.'::text),
(317426,35270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ta voiture est ... que ces SUV, et franchement, c''est cool.'::text,'plus petite'::text,'plus petite'::text,'la plus petite'::text,'Ta voiture est plus petite que ces SUV, et franchement, c''est cool.'::text),
(317429,35270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araban o SUV''lardan ... ve açıkçası bu çok havalı.'::text,'daha küçük'::text,'daha küçük'::text,'en küçük'::text,'Araban o SUV''lardan daha küçük ve açıkçası bu çok havalı.'::text),
(317430,35270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autód ... azoknál a terepjáróknál, és őszintén, ez menő.'::text,'kisebb'::text,'kisebb'::text,'legkisebb'::text,'Az autód kisebb azoknál a terepjáróknál, és őszintén, ez menő.'::text),
(317433,35271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du fährst das kleine Auto so ..., Respekt.'::text,'ruhig'::text,'ruhig'::text,'Ruhe'::text,'Du fährst das kleine Auto so ruhig, Respekt.'::text),
(317437,35271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти водиш цю маленьку машину так ..., респект.'::text,'спокійно'::text,'спокійний'::text,'спокій'::text,'Ти водиш цю маленьку машину так спокійно, респект.'::text),
(317436,35271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Conduces ese coche pequeño tan ..., respeto.'::text,'tranquilamente'::text,'tranquilo'::text,'tranquilidad'::text,'Conduces ese coche pequeño tan tranquilamente, respeto.'::text),
(317435,35271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu conduis cette petite voiture si ..., respect.'::text,'calmement'::text,'calme'::text,'calme'::text,'Tu conduis cette petite voiture si calmement, respect.'::text),
(317438,35271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O küçük arabayı çok ... sürüyorsun, saygılar.'::text,'sakince'::text,'sakin'::text,'sakinlik'::text,'O küçük arabayı çok sakince sürüyorsun, saygılar.'::text),
(317439,35271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan ... vezeted azt a kis autót, respekt.'::text,'nyugodtan'::text,'nyugodt'::text,'nyugalom'::text,'Olyan nyugodtan vezeted azt a kis autót, respekt.'::text),
(314634,34960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Suche dauert ... Minuten.'::text,'zehn'::text,'zehnte'::text,'Zehnen'::text,'Seine Suche dauert zehn Minuten.'::text),
(314638,34960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його пошуки тривають ... хвилин.'::text,'десять'::text,'десяту'::text,'десятки'::text,'Його пошуки тривають десять хвилин.'::text),
(314637,34960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su búsqueda dura ... minutos.'::text,'diez'::text,'décimo'::text,'diez'::text,'Su búsqueda dura diez minutos.'::text),
(314636,34960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa recherche dure ... minutes.'::text,'dix'::text,'dixième'::text,'dix'::text,'Sa recherche dure dix minutes.'::text),
(314639,34960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araması ... dakika sürüyor.'::text,'on'::text,'onuncu'::text,'onlar'::text,'Araması on dakika sürüyor.'::text),
(314640,34960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A keresése ... percig tart.'::text,'tíz'::text,'tizedik'::text,'tízesek'::text,'A keresése tíz percig tart.'::text),
(314643,34961,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ich glaube, deine Suche ... bald enden. Respekt.'::text,'wird'::text,'endet'::text,'endete'::text,'Ehrlich, ich glaube, deine Suche wird bald enden. Respekt.'::text),
(314647,34961,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, думаю, твої пошуки ... скоро. Респект.'::text,'закінчаться'::text,'закінчуються'::text,'закінчилися'::text,'Чесно, думаю, твої пошуки закінчаться скоро. Респект.'::text),
(314646,34961,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, creo que tu búsqueda ... pronto. Respeto.'::text,'terminará'::text,'termina'::text,'terminó'::text,'Sinceramente, creo que tu búsqueda terminará pronto. Respeto.'::text),
(314645,34961,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, je pense que ta recherche ... bientôt. Respect.'::text,'finira'::text,'finit'::text,'a fini'::text,'Franchement, je pense que ta recherche finira bientôt. Respect.'::text),
(314648,34961,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bence yakında araman ..., saygılar.'::text,'bitecek'::text,'biter'::text,'bitti'::text,'Açıkçası bence yakında araman bitecek, saygılar.'::text),
(314649,34961,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, szerintem a keresésed hamarosan ..., respekt.'::text,'véget fog érni'::text,'véget ér'::text,'véget ért'::text,'Őszintén, szerintem a keresésed hamarosan véget fog érni, respekt.'::text),
(314652,34962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Handy fehlt, also ... er eine Suche starten.'::text,'wird'::text,'wird'::text,'startet'::text,'Sein Handy fehlt, also wird er eine Suche starten.'::text),
(314656,34962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його телефон зник, тож він ... пошуки.'::text,'збирається почати'::text,'почне'::text,'починає'::text,'Його телефон зник, тож він збирається почати пошуки.'::text),
(314655,34962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le falta el móvil, así que ... una búsqueda.'::text,'va a empezar'::text,'empezará'::text,'empieza'::text,'Le falta el móvil, así que va a empezar una búsqueda.'::text),
(314654,34962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son téléphone a disparu, alors il ... une recherche.'::text,'va lancer'::text,'lancera'::text,'lance'::text,'Son téléphone a disparu, alors il va lancer une recherche.'::text),
(314657,34962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonu kayıp, bu yüzden bir arama ...'::text,'başlatacak'::text,'başlatacak'::text,'başlatır'::text,'Telefonu kayıp, bu yüzden bir arama başlatacak.'::text),
(314658,34962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eltűnt a telefonja, ezért ... keresni.'::text,'el fog kezdeni'::text,'el fog kezdeni'::text,'elkezd'::text,'Eltűnt a telefonja, ezért el fog kezdeni keresni.'::text),
(314670,34964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Seine Suche macht so viel ...!'::text,'Chaos'::text,'Chaos'::text,'ein Chaos'::text,'Katastrophe! Seine Suche macht so viel Chaos!'::text),
(314674,34964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Його пошуки роблять стільки ...!'::text,'безладу'::text,'безладів'::text,'безладу'::text,'Катастрофа! Його пошуки роблять стільки безладу!'::text),
(314673,34964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Su búsqueda arma tanto ...!'::text,'desorden'::text,'desorden'::text,'un desorden'::text,'¡Desastre! ¡Su búsqueda arma tanto desorden!'::text),
(314672,34964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cata ! Sa recherche fait tellement de ... !'::text,'bazar'::text,'bazar'::text,'un bazar'::text,'La cata ! Sa recherche fait tellement de bazar !'::text),
(314675,34964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Araması çok fazla ... yaratıyor!'::text,'dağınıklık'::text,'dağınıklıklar'::text,'bir dağınıklık'::text,'Felaket! Araması çok fazla dağınıklık yaratıyor!'::text),
(314676,34964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A keresése akkora ... csinál!'::text,'rendetlenséget'::text,'rendetlenségeket'::text,'egy rendetlenséget'::text,'Katasztrófa! A keresése akkora rendetlenséget csinál!'::text),
(314679,34965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Suche dauert so ... Minuten! Albtraum!'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Seine Suche dauert so viele Minuten! Albtraum!'::text),
(314683,34965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його пошуки тривають так ... хвилин! Жах!'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Його пошуки тривають так багато хвилин! Жах!'::text),
(314682,34965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su búsqueda dura ... minutos! ¡Pesadilla!'::text,'tantos'::text,'tanto'::text,'cualquier'::text,'¡Su búsqueda dura tantos minutos! ¡Pesadilla!'::text),
(314681,34965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa recherche prend ... minutes ! Cauchemar !'::text,'tellement de'::text,'tellement de'::text,'n''importe quelles'::text,'Sa recherche prend tellement de minutes ! Cauchemar !'::text),
