(314685,34965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A keresése olyan ... percig tart! Rémálom!'::text,'sok'::text,'sok'::text,'bármilyen'::text,'A keresése olyan sok percig tart! Rémálom!'::text),
(314688,34966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, in ihrer Wohnung ... gerade eine große Suche.'::text,'ist'::text,'sind'::text,'sein'::text,'Hör mal, ich hab gehört, in ihrer Wohnung ist gerade eine große Suche.'::text),
(314692,34966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що в їхній квартирі зараз ... великі пошуки.'::text,'є'::text,'є'::text,'бути'::text,'Слухай, я чула, що в їхній квартирі зараз є великі пошуки.'::text),
(314691,34966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que ahora mismo ... una gran búsqueda en su piso.'::text,'hay'::text,'hay'::text,'hay'::text,'Oye, me han dicho que ahora mismo hay una gran búsqueda en su piso.'::text),
(314690,34966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''en ce moment ... une grosse fouille dans leur appart.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Écoute, j''ai entendu dire qu''en ce moment il y a une grosse fouille dans leur appart.'::text),
(314693,34966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki şu an onların evinde büyük bir arama ...'::text,'var'::text,'var'::text,'olmak'::text,'Dinle, duydum ki şu an onların evinde büyük bir arama var.'::text),
(314694,34966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy most nagy keresés ... a lakásukban.'::text,'van'::text,'vannak'::text,'lenni'::text,'Figyelj, azt hallottam, hogy most nagy keresés van a lakásukban.'::text),
(313473,34831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du bleibst ruhig, wenn Räuber deine Bank ...'::text,'ausrauben'::text,'ausraubt'::text,'ausraubend'::text,'Respekt: Du bleibst ruhig, wenn Räuber deine Bank ausrauben.'::text),
(313477,34831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти лишаєшся спокійним, коли грабіжники ... твій банк.'::text,'грабують'::text,'грабує'::text,'грабуючи'::text,'Респект: ти лишаєшся спокійним, коли грабіжники грабують твій банк.'::text),
(313476,34831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: te quedas tranquilo cuando unos ladrones ... tu banco.'::text,'atracan'::text,'atraca'::text,'atracando'::text,'Respeto: te quedas tranquilo cuando unos ladrones atracan tu banco.'::text),
(313475,34831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu restes calme quand des braqueurs ... ta banque.'::text,'braquent'::text,'braque'::text,'braquant'::text,'Respect : tu restes calme quand des braqueurs braquent ta banque.'::text),
(313478,34831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: soyguncular bankanı ..., sen yine sakin kalıyorsun.'::text,'soyarlar'::text,'soyar'::text,'soyarak'::text,'Saygılar: soyguncular bankanı soyarlar, sen yine sakin kalıyorsun.'::text),
(313479,34831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: nyugodt maradsz, amikor rablók ... a bankodat.'::text,'kirabolják'::text,'kirabolja'::text,'kiraboló'::text,'Respekt: nyugodt maradsz, amikor rablók kirabolják a bankodat.'::text),
(313482,34832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, niemand ... dich ausrauben, deine Ruhe ist legendär.'::text,'kann'::text,'kann'::text,'ist'::text,'Ehrlich, niemand kann dich ausrauben, deine Ruhe ist legendär.'::text),
(313486,34832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ніхто не ... тебе пограбувати, твій спокій легендарний.'::text,'може'::text,'може'::text,'є'::text,'Чесно, ніхто не може тебе пограбувати, твій спокій легендарний.'::text),
(313485,34832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, nadie ... robarte, tu calma es icónica.'::text,'puede'::text,'puede'::text,'está'::text,'Sinceramente, nadie puede robarte, tu calma es icónica.'::text),
