(313504,34834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний план: учора ввечері він ... пограбувати не той банк.'::text,'спробував'::text,'пробує'::text,'пробувати'::text,'Бездоганний план: учора ввечері він спробував пограбувати не той банк.'::text),
