(325528,36170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фургон зупиняється на скелі ... вечірній час.'::text,'у'::text,'на'::text,'о'::text,'Фургон зупиняється на скелі у вечірній час.'::text),
(325527,36170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La furgoneta para ... la tarde en lo alto de un acantilado.'::text,'por'::text,'en'::text,'a'::text,'La furgoneta para por la tarde en lo alto de un acantilado.'::text),
(325526,36170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le van s''arrête ... soirée au sommet d''une falaise.'::text,'en'::text,'sur'::text,'à'::text,'Le van s''arrête en soirée au sommet d''une falaise.'::text),
(325529,36170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minibüs akşam ... bir uçurumun tepesinde duruyor.'::text,''::text,NULL::text,NULL::text,'Minibüs akşam bir uçurumun tepesinde duruyor.'::text),
(325530,36170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A furgon ... megáll egy szikla tetején.'::text,'este'::text,'estén'::text,'estekor'::text,'A furgon este megáll egy szikla tetején.'::text),
(325533,36171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... Freunde und ein Hund in einem Van, so cool.'::text,'drei'::text,'dritte'::text,'drei'::text,'Alter, drei Freunde und ein Hund in einem Van, so cool.'::text),
(325537,36171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... друзів і пес в одному фургоні, так круто.'::text,'троє'::text,'третій'::text,'троє'::text,'Бро, троє друзів і пес в одному фургоні, так круто.'::text),
(325536,36171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... amigos y un perro en una furgoneta, qué guay.'::text,'tres'::text,'tercer'::text,'tres'::text,'Tío, tres amigos y un perro en una furgoneta, qué guay.'::text),
(325535,36171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... potes et un chien dans un seul van, trop cool.'::text,'trois'::text,'troisième'::text,'trois'::text,'Frère, trois potes et un chien dans un seul van, trop cool.'::text),
(325538,36171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tek minibüste ... arkadaş ve bir köpek, çok havalı.'::text,'üç'::text,'üçüncü'::text,'üç'::text,'Kanka, tek minibüste üç arkadaş ve bir köpek, çok havalı.'::text),
(325539,36171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... haver és egy kutya egy furgonban, nagyon menő.'::text,'három'::text,'harmadik'::text,'három'::text,'Tesó, három haver és egy kutya egy furgonban, nagyon menő.'::text),
(325542,36172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Van ... gerade die Küstenstraße entlang, ikonisch.'::text,'fährt'::text,'fährt'::text,'fährt'::text,'Yo, der Van fährt gerade die Küstenstraße entlang, ikonisch.'::text),
(325546,36172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, фургон саме зараз ... прибережною дорогою, легендарно.'::text,'їде'::text,'їде'::text,'їде'::text,'Йо, фургон саме зараз їде прибережною дорогою, легендарно.'::text),
(325545,36172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la furgoneta ... por la carretera de la costa ahora mismo, icónico.'::text,'está bajando'::text,'baja'::text,'está bajando'::text,'Tío, la furgoneta está bajando por la carretera de la costa ahora mismo, icónico.'::text),
(325544,36172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le van ... la route côtière en ce moment, iconique.'::text,'est en train de descendre'::text,'descend'::text,'est en train de descendre'::text,'Yo, le van est en train de descendre la route côtière en ce moment, iconique.'::text),
(325547,36172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, minibüs şu an sahil yolundan ..., efsane.'::text,'iniyor'::text,'iner'::text,'iniyor'::text,'Kanka, minibüs şu an sahil yolundan iniyor, efsane.'::text),
(325548,36172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a furgon most épp ... a parti úton, ikonikus.'::text,'halad'::text,'halad'::text,'halad'::text,'Figyu, a furgon most épp halad a parti úton, ikonikus.'::text),
(318063,35341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst hüpft er weg, aber jetzt ... der weiche Lemur still.'::text,'sitzt'::text,'sitzt'::text,NULL::text,'Sonst hüpft er weg, aber jetzt sitzt der weiche Lemur still.'::text),
(318067,35341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він відстрибує, але зараз м''який лемур ... нерухомо.'::text,'сидить'::text,'сидить'::text,NULL::text,'Зазвичай він відстрибує, але зараз м''який лемур сидить нерухомо.'::text),
(318066,35341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente se aleja dando saltos, pero ahora el suave lémur ... quieto.'::text,'está sentado'::text,'se sienta'::text,NULL::text,'Normalmente se aleja dando saltos, pero ahora el suave lémur está sentado quieto.'::text),
(318065,35341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il s''éloigne en sautillant, mais là le lémurien tout doux ... immobile.'::text,'est assis'::text,'s''assoit'::text,NULL::text,'D''habitude il s''éloigne en sautillant, mais là le lémurien tout doux est assis immobile.'::text),
(318068,35341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde zıplayıp kaçar ama şimdi yumuşak lemur kıpırdamadan ...'::text,'oturuyor'::text,'oturur'::text,NULL::text,'Genelde zıplayıp kaçar ama şimdi yumuşak lemur kıpırdamadan oturuyor.'::text),
(318069,35341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában elugrál, de most a puha maki mozdulatlanul ...'::text,'ül'::text,'ül'::text,NULL::text,'Általában elugrál, de most a puha maki mozdulatlanul ül.'::text),
(318072,35342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, dass der Lemur morgen für mehr sanfte Streicheleinheiten ...'::text,'zurückkommen wird'::text,'zurückkommt'::text,'zurückkam'::text,'Ich glaube, dass der Lemur morgen für mehr sanfte Streicheleinheiten zurückkommen wird.'::text),
(318076,35342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, лемур завтра ... по ще більше ніжних погладжувань.'::text,'повернеться'::text,'повертається'::text,'повернувся'::text,'Думаю, лемур завтра повернеться по ще більше ніжних погладжувань.'::text),
(318075,35342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que el lémur ... mañana a por más caricias suaves.'::text,'volverá'::text,'vuelve'::text,'volvió'::text,'Creo que el lémur volverá mañana a por más caricias suaves.'::text),
(318074,35342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que le lémurien ... demain pour d''autres douces caresses.'::text,'reviendra'::text,'revient'::text,'est revenu'::text,'Je pense que le lémurien reviendra demain pour d''autres douces caresses.'::text),
(318077,35342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence lemur yarın daha fazla yumuşak okşama için geri ...'::text,'gelecek'::text,'gelir'::text,'geldi'::text,'Bence lemur yarın daha fazla yumuşak okşama için geri gelecek.'::text),
(318078,35342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem a maki holnap ... még több gyengéd simogatásért.'::text,'vissza fog jönni'::text,'visszajön'::text,'visszajött'::text,'Szerintem a maki holnap vissza fog jönni még több gyengéd simogatásért.'::text),
(318081,35343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie hat eine Karotte, also ... sie das weiche Fell streicheln, echt.'::text,'wird'::text,'wird'::text,'streichelt'::text,'Alter, sie hat eine Karotte, also wird sie das weiche Fell streicheln, echt.'::text),
(318085,35343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у неї морквина, тож вона ... це м''яке хутро, чесно.'::text,'збирається погладити'::text,'погладить'::text,'гладить'::text,'Бро, у неї морквина, тож вона збирається погладити це м''яке хутро, чесно.'::text),
(318084,35343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, tiene una zanahoria, así que ... ese pelaje suave, en serio.'::text,'va a acariciar'::text,'acariciará'::text,'acaricia'::text,'Tío, tiene una zanahoria, así que va a acariciar ese pelaje suave, en serio.'::text),
(318083,35343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle a une carotte, alors elle ... cette fourrure toute douce, sérieux.'::text,'va caresser'::text,'caressera'::text,'caresse'::text,'Frère, elle a une carotte, alors elle va caresser cette fourrure toute douce, sérieux.'::text),
(318086,35343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, elinde havuç var, bu yüzden o yumuşak tüyleri ..., cidden.'::text,'okşayacak'::text,'okşayacak'::text,'okşar'::text,'Kanka, elinde havuç var, bu yüzden o yumuşak tüyleri okşayacak, cidden.'::text),
(318087,35343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, van egy répája, úgyhogy ... megsimogatni azt a puha bundát, komolyan.'::text,'fogja'::text,'fogja'::text,'megsimogatja'::text,'Tesó, van egy répája, úgyhogy fogja megsimogatni azt a puha bundát, komolyan.'::text),
(318090,35344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel: 1 Karotte. Die Hand ist nah, also ... sie das weiche Fell berühren.'::text,'wird'::text,'wird'::text,NULL::text,'Ziel: 1 Karotte. Die Hand ist nah, also wird sie das weiche Fell berühren.'::text),
(318094,35344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль: 1 морквина. Рука близько, тож вона ... м''якого хутра.'::text,'збирається торкнутися'::text,'торкнеться'::text,NULL::text,'Ціль: 1 морквина. Рука близько, тож вона збирається торкнутися м''якого хутра.'::text),
(318093,35344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo: 1 zanahoria. La mano está cerca, así que ... el pelaje suave.'::text,'va a tocar'::text,'tocará'::text,NULL::text,'Objetivo: 1 zanahoria. La mano está cerca, así que va a tocar el pelaje suave.'::text),
(318092,35344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif : 1 carotte. La main est proche, donc elle ... la fourrure douce.'::text,'va toucher'::text,'touchera'::text,NULL::text,'Objectif : 1 carotte. La main est proche, donc elle va toucher la fourrure douce.'::text),
(318095,35344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef: 1 havuç. El yakın, bu yüzden yumuşak tüylere ...'::text,'dokunacak'::text,'dokunacak'::text,NULL::text,'Hedef: 1 havuç. El yakın, bu yüzden yumuşak tüylere dokunacak.'::text),
(318096,35344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél: 1 répa. A kéz közel van, ezért ... megérinteni a puha bundát.'::text,'fogja'::text,'fogja'::text,NULL::text,'Cél: 1 répa. A kéz közel van, ezért fogja megérinteni a puha bundát.'::text),
(318108,35346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lemuren-Regel: Du ... sanft mit weichem Fell sein. Und ehrlich, das bist du.'::text,'musst'::text,'musst'::text,'solltest'::text,'Lemuren-Regel: Du musst sanft mit weichem Fell sein. Und ehrlich, das bist du.'::text),
(318112,35346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило лемурів: ти ... бути ніжним із м''яким хутром. І чесно, ти такий.'::text,'маєш'::text,'мусиш'::text,'мав би'::text,'Правило лемурів: ти маєш бути ніжним із м''яким хутром. І чесно, ти такий.'::text),
(318111,35346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Norma de lémur: ... ser delicado con el pelaje suave. Y sinceramente, lo eres.'::text,'tienes que'::text,'debes'::text,'deberías'::text,'Norma de lémur: tienes que ser delicado con el pelaje suave. Y sinceramente, lo eres.'::text),
(318110,35346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Règle des lémuriens : tu ... être doux avec la fourrure douce. Et franchement, tu l''es.'::text,'dois'::text,'dois'::text,'devrais'::text,'Règle des lémuriens : tu dois être doux avec la fourrure douce. Et franchement, tu l''es.'::text),
(318113,35346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lemur kuralı: yumuşak tüylere karşı nazik ... — ve açıkçası, öylesin.'::text,'olmak zorundasın'::text,'olmalısın'::text,'olmalısın'::text,'Lemur kuralı: yumuşak tüylere karşı nazik olmak zorundasın — ve açıkçası, öylesin.'::text),
(318114,35346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makiszabály: gyengédnek ... lenned a puha bundával. És őszintén, az is vagy.'::text,'kell'::text,'kell'::text,'kellene'::text,'Makiszabály: gyengédnek kell lenned a puha bundával. És őszintén, az is vagy.'::text),
(318117,35347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du streichelst sein weiches Fell so ..., Respekt.'::text,'sanft'::text,'sanft'::text,'Sanftheit'::text,'Du streichelst sein weiches Fell so sanft, Respekt.'::text),
(318121,35347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти гладиш його м''яке хутро так ..., респект.'::text,'ніжно'::text,'ніжний'::text,'ніжність'::text,'Ти гладиш його м''яке хутро так ніжно, респект.'::text),
(318120,35347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Acaricias su pelaje suave tan ..., respeto.'::text,'delicadamente'::text,'delicado'::text,'delicadeza'::text,'Acaricias su pelaje suave tan delicadamente, respeto.'::text),
(318119,35347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu caresses sa fourrure douce si ..., respect.'::text,'doucement'::text,'doux'::text,'douceur'::text,'Tu caresses sa fourrure douce si doucement, respect.'::text),
(318122,35347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun yumuşak tüylerini çok ... okşuyorsun, saygılar.'::text,'nazikçe'::text,'nazik'::text,'naziklik'::text,'Onun yumuşak tüylerini çok nazikçe okşuyorsun, saygılar.'::text),
(318123,35347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan ... simogatod a puha bundáját, respekt.'::text,'gyengéden'::text,'gyengéd'::text,'gyengédség'::text,'Olyan gyengéden simogatod a puha bundáját, respekt.'::text),
(328341,36483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Haus ... einen Hof mit einem hohen Zaun.'::text,'hat'::text,'haben'::text,'hat'::text,'Das Haus hat einen Hof mit einem hohen Zaun.'::text),
(328345,36483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Будинок ... подвір''я з високим парканом.'::text,'має'::text,'мати'::text,'має'::text,'Будинок має подвір''я з високим парканом.'::text),
(328344,36483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La casa ... un patio con una valla alta.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'La casa tiene un patio con una valla alta.'::text),
(328343,36483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maison ... une cour avec une haute clôture.'::text,'a'::text,'ont'::text,'a'::text,'La maison a une cour avec une haute clôture.'::text),
(328346,36483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evin yüksek çitli bir bahçesi ...'::text,'var'::text,'var'::text,'var'::text,'Evin yüksek çitli bir bahçesi var.'::text),
(328347,36483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A háznak ... egy udvara magas kerítéssel.'::text,'van'::text,'van'::text,'van'::text,'A háznak van egy udvara magas kerítéssel.'::text),
(328350,36484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe ... über das Gras im Hof.'::text,'rennt'::text,'rennen'::text,'rennend'::text,'Der Welpe rennt über das Gras im Hof.'::text),
(328354,36484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя ... травою подвір''я.'::text,'біжить'::text,'бігти'::text,'біжучи'::text,'Цуценя біжить травою подвір''я.'::text),
(328353,36484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cachorro ... por la hierba del patio.'::text,'corre'::text,'correr'::text,'corriendo'::text,'El cachorro corre por la hierba del patio.'::text),
(328352,36484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot ... sur l''herbe de la cour.'::text,'court'::text,'courir'::text,'courant'::text,'Le chiot court sur l''herbe de la cour.'::text),
(328355,36484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru köpek bahçenin çimlerinin üstünde ...'::text,'koşar'::text,'koşmak'::text,'koşarak'::text,'Yavru köpek bahçenin çimlerinin üstünde koşar.'::text),
(328356,36484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya ... az udvar füvén.'::text,'fut'::text,'futni'::text,'futó'::text,'A kiskutya fut az udvar füvén.'::text),
(328368,36486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Im Hof ist so viel trockenes ...!'::text,'Gras'::text,'Gras'::text,'ein Gras'::text,'Katastrophe! Im Hof ist so viel trockenes Gras!'::text),
(328372,36486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! На подвір''ї стільки сухої ...!'::text,'трави'::text,'трав'::text,'трави'::text,'Катастрофа! На подвір''ї стільки сухої трави!'::text),
(328371,36486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Hay tanta ... seca en el patio!'::text,'hierba'::text,'hierba'::text,'una hierba'::text,'¡Desastre! ¡Hay tanta hierba seca en el patio!'::text),
(328370,36486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cata ! Il y a tellement ... sèche dans la cour !'::text,'d''herbe'::text,'d''herbe'::text,'d''une herbe'::text,'La cata ! Il y a tellement d''herbe sèche dans la cour !'::text),
(328373,36486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Bahçede çok fazla kuru ... var!'::text,'çim'::text,'çimler'::text,'bir çim'::text,'Felaket! Bahçede çok fazla kuru çim var!'::text),
(328374,36486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Annyi száraz ... van az udvaron!'::text,'fű'::text,'fű'::text,'egy fű'::text,'Katasztrófa! Annyi száraz fű van az udvaron!'::text),
(328377,36487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Der Hof hat so ... trockene Stellen!'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Albtraum! Der Hof hat so viele trockene Stellen!'::text),
(328381,36487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! На подвір''ї так ... сухих плям!'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Жах! На подвір''ї так багато сухих плям!'::text),
(328380,36487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡El patio tiene ... zonas secas!'::text,'tantas'::text,'tanta'::text,'cualquier'::text,'¡Pesadilla! ¡El patio tiene tantas zonas secas!'::text),
(328379,36487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! La cour a ... plaques sèches !'::text,'tellement de'::text,'tellement de'::text,'n''importe quelles'::text,'Cauchemar ! La cour a tellement de plaques sèches !'::text),
(328382,36487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bahçede o kadar ... kuru yer var ki!'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Kâbus! Bahçede o kadar çok kuru yer var ki!'::text),
(328383,36487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Az udvaron olyan ... száraz folt van!'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Rémálom! Az udvaron olyan sok száraz folt van!'::text),
(328395,36489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hof ist zum Spielen da, also ... der Welpe im Hof spielen.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Der Hof ist zum Spielen da, also sollte der Welpe im Hof spielen.'::text),
(328399,36489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подвір''я — для гри, тож цуценя ... гратися на подвір''ї.'::text,'мало б'::text,'мало б'::text,'буде'::text,'Подвір''я — для гри, тож цуценя мало б гратися на подвір''ї.'::text),
(328398,36489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El patio es para jugar, así que el cachorro ... jugar en el patio.'::text,'debería'::text,'debería'::text,'deberá'::text,'El patio es para jugar, así que el cachorro debería jugar en el patio.'::text),
(328397,36489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cour, c''est pour jouer, donc le chiot ... jouer dans la cour.'::text,'devrait'::text,'devrait'::text,'devra'::text,'La cour, c''est pour jouer, donc le chiot devrait jouer dans la cour.'::text),
(328400,36489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçe oyun içindir, bu yüzden yavru köpek bahçede ...'::text,'oynamalı'::text,'oynamalı'::text,'oynayacak'::text,'Bahçe oyun içindir, bu yüzden yavru köpek bahçede oynamalı.'::text),
(328401,36489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az udvar játszásra való, ezért a kiskutyának az udvaron ... játszania.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Az udvar játszásra való, ezért a kiskutyának az udvaron kellene játszania.'::text),
(328404,36490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, angeblich ist der Welpe gerannt, ... er im Hof eine Kamera gesehen hat.'::text,'weil'::text,'aber'::text,'also'::text,'Also, angeblich ist der Welpe gerannt, weil er im Hof eine Kamera gesehen hat.'::text),
(328408,36490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, цуценя побігло, ... побачило на подвір''ї камеру.'::text,'бо'::text,'але'::text,'тому'::text,'Коротше, кажуть, цуценя побігло, бо побачило на подвір''ї камеру.'::text),
(328407,36490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, dicen que el cachorro echó a correr ... vio una cámara en el patio.'::text,'porque'::text,'pero'::text,'así que'::text,'A ver, dicen que el cachorro echó a correr porque vio una cámara en el patio.'::text),
(328406,36490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment le chiot a couru ... il a vu une caméra dans la cour.'::text,'parce qu'''::text,'mais'::text,'donc'::text,'Bon alors, apparemment le chiot a couru parce qu'' il a vu une caméra dans la cour.'::text),
(328409,36490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani güya yavru köpek koştu ... bahçede bir kamera gördü.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Yani güya yavru köpek koştu çünkü bahçede bir kamera gördü.'::text),
(328410,36490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag a kiskutya elfutott, ... meglátott egy kamerát az udvaron.'::text,'mert'::text,'de'::text,'ezért'::text,'Szóval állítólag a kiskutya elfutott, mert meglátott egy kamerát az udvaron.'::text),
(300306,33368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Haustür ist die Tür seines Zuhauses.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Haustür ist die Tür seines Zuhauses.'::text),
(300310,33368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вхідні двері — це двері його дому.'::text,'Ці'::text,'Ці'::text,'Ті'::text,'Ці вхідні двері — це двері його дому.'::text),
(300309,33368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... puerta principal es la puerta de su casa.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta puerta principal es la puerta de su casa.'::text),
(300308,33368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... porte d''entrée est la porte de sa maison.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette porte d''entrée est la porte de sa maison.'::text),
(300311,33368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ön kapı onun evinin kapısı.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu ön kapı onun evinin kapısı.'::text),
(300312,33368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a bejárati ajtó az otthona ajtaja.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a bejárati ajtó az otthona ajtaja.'::text),
(300315,33369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe verlässt ... Zuhause, also ist er nicht zu Hause.'::text,'sein'::text,'es ist'::text,'es'::text,'Der Welpe verlässt sein Zuhause, also ist er nicht zu Hause.'::text),
(300319,33369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя покидає ... дім, тож його немає вдома.'::text,'свій'::text,'воно є'::text,'воно'::text,'Цуценя покидає свій дім, тож його немає вдома.'::text),
(300318,33369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cachorro sale de ... casa, así que no está en casa.'::text,'su'::text,'está'::text,'él'::text,'El cachorro sale de su casa, así que no está en casa.'::text),
(300317,33369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot quitte ... maison, donc il n''est pas à la maison.'::text,'sa'::text,'c''est'::text,'il'::text,'Le chiot quitte sa maison, donc il n''est pas à la maison.'::text),
(300320,33369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru köpek ... evinden çıkıyor, yani evde değil.'::text,'onun'::text,'o'::text,'o'::text,'Yavru köpek onun evinden çıkıyor, yani evde değil.'::text),
(300321,33369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya elhagyja az ..., tehát nincs otthon.'::text,'otthonát'::text,'az'::text,'az'::text,'A kiskutya elhagyja az otthonát, tehát nincs otthon.'::text),
(300324,33370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hast du diesen Hut her? Du verlässt das Haus mit Stil, ehrlich.'::text,'Wo'::text,'Wer'::text,'Was'::text,'Wo hast du diesen Hut her? Du verlässt das Haus mit Stil, ehrlich.'::text),
(300328,33370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ти взяв цю панамку? Ти виходиш з дому стильно, чесно.'::text,'Де'::text,'Хто'::text,'Що'::text,'Де ти взяв цю панамку? Ти виходиш з дому стильно, чесно.'::text),
(300327,33370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... conseguiste ese gorro? Sales de casa con estilo, en serio.'::text,'Dónde'::text,'Quién'::text,'Qué'::text,'¿Dónde conseguiste ese gorro? Sales de casa con estilo, en serio.'::text),
(300326,33370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tu as eu ce chapeau ? Tu sors de chez toi avec style, franchement.'::text,'Où'::text,'Qui'::text,'Que'::text,'Où tu as eu ce chapeau ? Tu sors de chez toi avec style, franchement.'::text),
(300329,33370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şapkayı ... buldun? Evden tarzınla çıkıyorsun, açıkçası.'::text,'nereden'::text,'kim'::text,'ne'::text,'O şapkayı nereden buldun? Evden tarzınla çıkıyorsun, açıkçası.'::text),
(300330,33370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... szerezted azt a kalapot? Stílusosan indulsz el otthonról, őszintén.'::text,'Honnan'::text,'Ki'::text,'Mi'::text,'Honnan szerezted azt a kalapot? Stílusosan indulsz el otthonról, őszintén.'::text),
(300342,33372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch: Du verlässt um ... Uhr stylisch das Haus.'::text,'neun'::text,'neunte'::text,'Neunen'::text,'Irgendwie ikonisch: Du verlässt um neun Uhr stylisch das Haus.'::text),
(300346,33372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи легендарно: ти виходиш з дому стильно о ...'::text,'дев''ятій'::text,'дев''ятій'::text,'дев''ятках'::text,'Трохи легендарно: ти виходиш з дому стильно о дев''ятій.'::text),
(300345,33372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante icónico: sales de casa con estilo a las ...'::text,'nueve'::text,'novena'::text,'nueve'::text,'Bastante icónico: sales de casa con estilo a las nueve.'::text),
(300344,33372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu iconique : tu sors de chez toi avec style à ... heures.'::text,'neuf'::text,'neuvième'::text,'neuf'::text,'Un peu iconique : tu sors de chez toi avec style à neuf heures.'::text),
(300347,33372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz efsane: evden tarzınla saat ... çıkıyorsun.'::text,'dokuzda'::text,'dokuzuncuda'::text,'dokuzlarda'::text,'Biraz efsane: evden tarzınla saat dokuzda çıkıyorsun.'::text),
(300348,33372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit ikonikus: ... órakor stílusosan indulsz el otthonról.'::text,'kilenc'::text,'kilencedik'::text,'kilencesek'::text,'Kicsit ikonikus: kilenc órakor stílusosan indulsz el otthonról.'::text),
(300351,33373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr unauffällig, logisch: Gestern ... der Welpe mit Fischerhut das Haus.'::text,'verließ'::text,'verlässt'::text,'verließ'::text,'Sehr unauffällig, logisch: Gestern verließ der Welpe mit Fischerhut das Haus.'::text),
(300355,33373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже непомітно, звісно: учора цуценя ... з дому в панамці.'::text,'пішло'::text,'іде'::text,'пішло'::text,'Дуже непомітно, звісно: учора цуценя пішло з дому в панамці.'::text),
(300354,33373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy discreto, claro: ayer el cachorro ... de casa con un gorro de pescador.'::text,'salió'::text,'sale'::text,'salió'::text,'Muy discreto, claro: ayer el cachorro salió de casa con un gorro de pescador.'::text),
(300353,33373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très discret, évidemment : hier, le chiot ... de la maison avec un bob.'::text,'est sorti'::text,'sort'::text,'est sorti'::text,'Très discret, évidemment : hier, le chiot est sorti de la maison avec un bob.'::text),
(300356,33373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok dikkat çekmeyen, tabii ki: dün yavru köpek balıkçı şapkasıyla evden ...'::text,'çıktı'::text,'çıkar'::text,'çıktı'::text,'Çok dikkat çekmeyen, tabii ki: dün yavru köpek balıkçı şapkasıyla evden çıktı.'::text),
(300357,33373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon feltűnésmentes, persze: tegnap a kiskutya egy halászsapkában ... el otthonról.'::text,'ment'::text,'megy'::text,'ment'::text,'Nagyon feltűnésmentes, persze: tegnap a kiskutya egy halászsapkában ment el otthonról.'::text),
(300369,33375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe ... jetzt von seinem Zuhause weg.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Der Welpe läuft jetzt von seinem Zuhause weg.'::text),
(300373,33375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя зараз ... геть від свого дому.'::text,'іде'::text,'іде'::text,'іде'::text,'Цуценя зараз іде геть від свого дому.'::text),
(300372,33375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cachorro ... ahora lejos de su casa.'::text,'está caminando'::text,'camina'::text,'está caminando'::text,'El cachorro está caminando ahora lejos de su casa.'::text),
(300371,33375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot ... loin de chez lui maintenant.'::text,'est en train de marcher'::text,'marche'::text,'est en train de marcher'::text,'Le chiot est en train de marcher loin de chez lui maintenant.'::text),
(300374,33375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru köpek şimdi evinden uzaklaşarak ...'::text,'yürüyor'::text,'yürür'::text,'yürüyor'::text,'Yavru köpek şimdi evinden uzaklaşarak yürüyor.'::text),
(300375,33375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya most ... el az otthonától.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'A kiskutya most sétál el az otthonától.'::text),
(297543,33061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schimpanse trägt normalerweise Braun, aber heute ... er Grün. Grün ist Grün.'::text,'trägt'::text,'trägt'::text,NULL::text,'Der Schimpanse trägt normalerweise Braun, aber heute trägt er Grün. Grün ist Grün.'::text),
(297547,33061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шимпанзе зазвичай носить коричневе, а сьогодні ... зелене. Зелене — це зелене.'::text,'носить'::text,'носить'::text,NULL::text,'Шимпанзе зазвичай носить коричневе, а сьогодні носить зелене. Зелене — це зелене.'::text),
(297546,33061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chimpancé suele llevar marrón, pero hoy ... verde. El verde es verde.'::text,'está llevando'::text,'lleva'::text,NULL::text,'El chimpancé suele llevar marrón, pero hoy está llevando verde. El verde es verde.'::text),
(297545,33061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chimpanzé porte du marron d''habitude, mais aujourd''hui il ... du vert. Le vert, c''est vert.'::text,'porte'::text,'porte'::text,NULL::text,'Le chimpanzé porte du marron d''habitude, mais aujourd''hui il porte du vert. Le vert, c''est vert.'::text),
(297548,33061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şempanze genelde kahverengi giyer ama bugün yeşil ... — yeşil yeşildir.'::text,'giyiyor'::text,'giyer'::text,NULL::text,'Şempanze genelde kahverengi giyer ama bugün yeşil giyiyor — yeşil yeşildir.'::text),
(297549,33061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csimpánz általában barnát hord, de ma ... zöldet. A zöld az zöld.'::text,'hord'::text,'hord'::text,NULL::text,'A csimpánz általában barnát hord, de ma hord zöldet. A zöld az zöld.'::text),
(297561,33063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, die Katze ... zehn weitere grüne Umhänge kaufen.'::text,'wird'::text,'werden'::text,'wird'::text,'Hör mal, ich hab gehört, die Katze wird zehn weitere grüne Umhänge kaufen.'::text),
(297565,33063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що кіт ... купити ще десять зелених накидок.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Слухай, я чула, що кіт збирається купити ще десять зелених накидок.'::text),
(297564,33063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que el gato ... comprar diez capas verdes más.'::text,'va a'::text,'van a'::text,'va a'::text,'Oye, me han dicho que el gato va a comprar diez capas verdes más.'::text),
(297563,33063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que le chat ... acheter dix capes vertes de plus.'::text,'va'::text,'vont'::text,'va'::text,'Écoute, j''ai entendu que le chat va acheter dix capes vertes de plus.'::text),
(297566,33063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki kedi on tane daha yeşil pelerin ...'::text,'alacak'::text,'alacaklar'::text,'alacak'::text,'Dinle, duydum ki kedi on tane daha yeşil pelerin alacak.'::text),
(297567,33063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a macska még tíz zöld köpenyt ... venni.'::text,'fog'::text,'fognak'::text,'fog'::text,'Figyelj, azt hallottam, hogy a macska még tíz zöld köpenyt fog venni.'::text),
(297570,33064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine Einwände: Dampf an der grünen Wand, also ... der Afro bald glatt sein.'::text,'wird'::text,'wird'::text,NULL::text,'Keine Einwände: Dampf an der grünen Wand, also wird der Afro bald glatt sein.'::text),
(297574,33064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без зауважень: пара біля зеленої стіни, тож афро скоро ... бути прямим.'::text,'збирається'::text,'буде'::text,NULL::text,'Без зауважень: пара біля зеленої стіни, тож афро скоро збирається бути прямим.'::text),
(297573,33064,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nada que objetar: vapor junto a la pared verde, así que el afro ... estar liso pronto.'::text,'va a'::text,NULL::text,NULL::text,'Nada que objetar: vapor junto a la pared verde, así que el afro va a estar liso pronto.'::text),
(297572,33064,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rien à redire : de la vapeur près du mur vert, donc l''afro ... être lisse bientôt.'::text,'va'::text,NULL::text,NULL::text,'Rien à redire : de la vapeur près du mur vert, donc l''afro va être lisse bientôt.'::text),
(297575,33064,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diyecek yok: yeşil duvarın yanında buhar var, bu yüzden afro yakında düz ...'::text,'olacak'::text,'olacak'::text,NULL::text,'Diyecek yok: yeşil duvarın yanında buhar var, bu yüzden afro yakında düz olacak.'::text),
(297576,33064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nincs mit hozzátenni: gőz a zöld falnál, úgyhogy az afró hamarosan egyenes ... lenni.'::text,'fog'::text,'fog'::text,NULL::text,'Nincs mit hozzátenni: gőz a zöld falnál, úgyhogy az afró hamarosan egyenes fog lenni.'::text),
(297579,33065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super Arbeit, logisch: viel weniger ... vor der grünen Wand.'::text,'Haar'::text,'Haar'::text,'ein Haar'::text,'Super Arbeit, logisch: viel weniger Haar vor der grünen Wand.'::text),
(297583,33065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, звісно: набагато менше ... перед зеленою стіною.'::text,'волосся'::text,'волосся'::text,'волосини'::text,'Чудова робота, звісно: набагато менше волосся перед зеленою стіною.'::text),
(297582,33065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, claro: mucho menos ... delante de la pared verde.'::text,'pelo'::text,'pelo'::text,'un pelo'::text,'Buen trabajo, claro: mucho menos pelo delante de la pared verde.'::text),
(297581,33065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super boulot, évidemment : beaucoup moins de ... devant le mur vert.'::text,'cheveux'::text,'cheveux'::text,'un cheveu'::text,'Super boulot, évidemment : beaucoup moins de cheveux devant le mur vert.'::text),
(297584,33065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, tabii ki: yeşil duvarın önünde çok daha az ...'::text,'saç'::text,'saçlar'::text,'bir saç'::text,'Harika iş, tabii ki: yeşil duvarın önünde çok daha az saç.'::text),
(297585,33065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, persze: sokkal kevesebb ... a zöld fal előtt.'::text,'haj'::text,'haj'::text,'egy hajszál'::text,'Szép munka, persze: sokkal kevesebb haj a zöld fal előtt.'::text),
(297588,33066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der Theke sind ... grüne Pflanzen.'::text,'einige'::text,'irgendwelche'::text,'viel'::text,'Auf der Theke sind einige grüne Pflanzen.'::text),
(297592,33066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На прилавку є ... зелені рослини.'::text,'деякі'::text,'будь-які'::text,'багато'::text,'На прилавку є деякі зелені рослини.'::text),
